fn qwen3_text_output_scenario_from_args() -> Option<PathBuf> {
    let mut args = env::args_os().skip(1);
    match args.next() {
        Some(mode) if mode == "qwen3-text-output" => Some(
            args.next()
                .map(PathBuf::from)
                .unwrap_or_else(default_scenario_path),
        ),
        _ => None,
    }
}

