fn run_lingqu_memory_resolve_paper_engram_table_row_blocks_cli(
    args: &[String],
) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let layer = required_cli_u64(args, "--layer")?;
    let order = required_cli_u64(args, "--order")?;
    let head = required_cli_u64(args, "--head")?;
    let row_start = required_cli_u64(args, "--row-start")?;
    let row_end = required_cli_u64(args, "--row-end")?;
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);
    let output_path = optional_cli_path(args, "--output")?;

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let mut memory_service = LingquMemoryService::new();
    rebuild_lingqu_memory_all_paper_engram_registries(&mut memory_service, &mut durable_store)
        .context("rebuild paper engram registries")?;

    let module_id = paper_engram_module_id_from_cli(args, &memory_service)?;
    let request = PaperEngramTableRowBlockRequest {
        request_id: format!(
            "paper-engram-row-blocks/{module_id}/layer-{layer}/order-{order}/head-{head}/rows-{row_start}-{row_end}"
        ),
        module_id,
        layer: u32::try_from(layer).context("--layer exceeds u32")?,
        order: u8::try_from(order).context("--order exceeds u8")?,
        head: u32::try_from(head).context("--head exceeds u32")?,
        row_start,
        row_end,
        created_at_us: now_us,
    };
    let response = memory_service
        .resolve_paper_engram_table_row_blocks(request)
        .context("resolve paper engram table row blocks")?;
    if let Some(path) = &output_path {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("create row block output dir {}", parent.display()))?;
        }
        fs::write(
            path,
            serde_json::to_vec_pretty(&response).context("encode row block response")?,
        )
        .with_context(|| format!("write row block response {}", path.display()))?;
    }

    println!("lingqu_memory_service");
    println!("  mode: resolve-paper-engram-table-row-blocks");
    println!("  store_path: {}", store_path.display());
    println!("  module_id: {}", response.module_id);
    println!(
        "  table: layer={} order={} head={} rows={}..{}",
        response.layer, response.order, response.head, response.row_start, response.row_end
    );
    println!(
        "  shard: {} rows={}..{}",
        response.shard_id, response.shard_row_start, response.shard_row_end
    );
    println!(
        "  row_payload: offset_bytes={} bytes={}",
        response.row_payload_offset_bytes, response.row_payload_bytes
    );
    println!(
        "  block_payload_refs: {}",
        response.block_payload_refs.len()
    );
    if let Some(path) = output_path {
        println!("  output_path: {}", path.display());
    }
    Ok(())
}

fn run_lingqu_memory_plan_paper_engram_row_prefetch_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let from_step = optional_cli_u64(args, "--from-step")?.unwrap_or(0);
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);
    let output_path = optional_cli_path(args, "--output")?;

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let mut memory_service = LingquMemoryService::new();
    rebuild_lingqu_memory_all_paper_engram_registries(&mut memory_service, &mut durable_store)
        .context("rebuild paper engram registries")?;

    let module_id = paper_engram_module_id_from_cli(args, &memory_service)?;
    let runtime = memory_service
        .resolve_paper_engram_runtime_artifacts(&module_id)
        .context("resolve paper engram runtime artifacts for row prefetch")?;
    let canonical_history = parse_paper_engram_canonical_history_arg_or_file(
        args,
        Some(runtime.tokenizer_projection.projection_checksum),
    )?;
    let request = PaperEngramTableRowPrefetchRequest {
        request_id: format!("paper-engram-row-prefetch/{module_id}/from-{from_step}"),
        module_id,
        canonical_history,
        from_step,
        created_at_us: now_us,
    };
    let plan = memory_service
        .plan_paper_engram_table_row_prefetch(request)
        .context("plan paper engram row prefetch")?;
    if let Some(path) = &output_path {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("create row prefetch output dir {}", parent.display()))?;
        }
        fs::write(
            path,
            serde_json::to_vec_pretty(&plan).context("encode row prefetch plan")?,
        )
        .with_context(|| format!("write row prefetch plan {}", path.display()))?;
    }

    let unique_shards = plan
        .rows
        .iter()
        .map(|row| row.shard_id.as_str())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    println!("lingqu_memory_service");
    println!("  mode: plan-paper-engram-row-prefetch");
    println!("  store_path: {}", store_path.display());
    println!("  module_id: {}", plan.module_id);
    println!("  canonical_history_len: {}", plan.canonical_history_len);
    println!("  from_step: {}", plan.from_step);
    println!("  row_refs: {}", plan.rows.len());
    println!("  unique_shards: {}", unique_shards);
    if let Some(path) = output_path {
        println!("  output_path: {}", path.display());
    }
    Ok(())
}

fn run_lingqu_memory_publish_paper_engram_row_prefetch_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let object_store_path = PathBuf::from(required_cli_arg(args, "--object-store")?);
    let module_id = paper_engram_module_id_from_store_cli(args, &store_path)?;
    let registry_dir = PathBuf::from(required_cli_arg(args, "--registry-dir")?);
    let from_step = optional_cli_u64(args, "--from-step")?.unwrap_or(0);
    let owner_entity = optional_cli_u64(args, "--owner-entity")?.unwrap_or(0);
    let producer_entity = optional_cli_u64(args, "--producer-entity")?.unwrap_or(0);
    let owner_entity =
        u32::try_from(owner_entity).map_err(|_| anyhow::anyhow!("--owner-entity exceeds u32"))?;
    let producer_entity = u32::try_from(producer_entity)
        .map_err(|_| anyhow::anyhow!("--producer-entity exceeds u32"))?;
    let expected_projection_checksum =
        paper_engram_tokenizer_projection_checksum_for_module(&store_path, &module_id)?;
    let canonical_history =
        parse_paper_engram_canonical_history_arg_or_file(args, Some(expected_projection_checksum))?;

    let publication = publish_w5_paper_engram_row_prefetch_from_runtime(
        &store_path,
        &object_store_path,
        &module_id,
        &registry_dir,
        canonical_history,
        from_step,
        owner_entity,
        producer_entity,
    )?;

    println!("lingqu_memory_service");
    println!("  mode: publish-paper-engram-row-prefetch");
    println!("  store_path: {}", store_path.display());
    println!("  object_store_path: {}", object_store_path.display());
    println!("  module_id: {}", publication.module_id);
    println!("  registry_dir: {}", registry_dir.display());
    println!(
        "  {}={}",
        SIM_QWEN3_GUEST_ENGRAM_ROW_PREFETCH_REF, publication.prefetch_ref_hex
    );
    println!(
        "  {}={}",
        SIM_UAPI_QWEN3_OBJECT_SERVICE_SNAPSHOT,
        publication.object_service_snapshot_path.display()
    );
    println!("  row_refs: {}", publication.row_refs);
    println!("  unique_shards: {}", publication.unique_shards);
    println!(
        "  prefetch_manifest_bytes: {}",
        publication.prefetch_manifest_bytes
    );
    Ok(())
}

fn parse_paper_engram_canonical_history_arg_or_file(
    args: &[String],
    expected_projection_checksum: Option<u64>,
) -> anyhow::Result<Vec<u64>> {
    let canonical_csv = optional_cli_arg(args, "--canonical-history")?;
    let canonical_file = optional_cli_arg(args, "--canonical-history-file")?;
    let raw_csv = optional_cli_arg(args, "--raw-history")?;
    let raw_file = optional_cli_arg(args, "--raw-history-file")?;
    let canonical_present = canonical_csv.is_some() || canonical_file.is_some();
    let raw_present = raw_csv.is_some() || raw_file.is_some();

    match (canonical_present, raw_present) {
        (true, true) => {
            anyhow::bail!(
                "conflicting paper Engram history arguments: use canonical history or raw history, not both"
            );
        }
        (true, false) => {
            parse_u64_csv_arg_or_file(args, "--canonical-history", "--canonical-history-file")
        }
        (false, true) => {
            let raw_history =
                parse_u64_csv_arg_or_file(args, "--raw-history", "--raw-history-file")?;
            let projection_path = optional_cli_path(args, "--tokenizer-projection")?
                .ok_or_else(|| anyhow::anyhow!("--raw-history requires --tokenizer-projection"))?;
            let projection = qwen3_engram_tokenizer_projection_from_path(&projection_path)?;
            if let Some(expected) = expected_projection_checksum {
                if projection.aggregate_checksum != expected {
                    anyhow::bail!(
                        "paper Engram raw history tokenizer projection checksum mismatch: expected 0x{expected:016x} got 0x{:016x}",
                        projection.aggregate_checksum
                    );
                }
            }
            let projection = qwen3_engram_projection_map(&projection)?;
            raw_history
                .into_iter()
                .map(|token_id| {
                    projection.get(&token_id).copied().ok_or_else(|| {
                        anyhow::anyhow!(
                            "tokenizer projection {} does not contain raw token {}",
                            projection_path.display(),
                            token_id
                        )
                    })
                })
                .collect()
        }
        (false, false) => {
            anyhow::bail!(
                "missing required paper Engram history: provide --canonical-history/--canonical-history-file or --raw-history/--raw-history-file with --tokenizer-projection"
            );
        }
    }
}

fn paper_engram_tokenizer_projection_checksum_for_module(
    store_path: &Path,
    module_id: &str,
) -> anyhow::Result<u64> {
    let mut durable_store = load_lingqu_memory_durable_store(store_path)?;
    let mut memory_service = LingquMemoryService::new();
    rebuild_lingqu_memory_all_paper_engram_registries(&mut memory_service, &mut durable_store)
        .context("rebuild paper engram registries")?;
    let runtime = memory_service
        .resolve_paper_engram_runtime_artifacts(module_id)
        .context("resolve paper engram runtime artifacts for row prefetch")?;
    Ok(runtime.tokenizer_projection.projection_checksum)
}

fn run_lingqu_memory_publish_paper_engram_state_ref_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let object_store_path = PathBuf::from(required_cli_arg(args, "--object-store")?);
    let module_id = paper_engram_module_id_from_store_cli(args, &store_path)?;
    let registry_dir = PathBuf::from(required_cli_arg(args, "--registry-dir")?);
    let owner_entity = optional_cli_u64(args, "--owner-entity")?.unwrap_or(0);
    let producer_entity = optional_cli_u64(args, "--producer-entity")?.unwrap_or(0);
    let owner_entity =
        u32::try_from(owner_entity).map_err(|_| anyhow::anyhow!("--owner-entity exceeds u32"))?;
    let producer_entity = u32::try_from(producer_entity)
        .map_err(|_| anyhow::anyhow!("--producer-entity exceeds u32"))?;

    let publication = publish_w5_paper_engram_state_ref_from_runtime(
        &store_path,
        &object_store_path,
        &module_id,
        &registry_dir,
        owner_entity,
        producer_entity,
    )?;

    println!("lingqu_memory_service");
    println!("  mode: publish-paper-engram-state-ref");
    println!("  store_path: {}", store_path.display());
    println!("  object_store_path: {}", object_store_path.display());
    println!("  module_id: {}", module_id);
    println!("  registry_dir: {}", registry_dir.display());
    println!(
        "  {}={}",
        SIM_QWEN3_GUEST_ENGRAM_STATE_REF, publication.state_ref_hex
    );
    if let Some(snapshot_path) = &publication.object_service_snapshot_path {
        println!(
            "  {}={}",
            SIM_UAPI_QWEN3_OBJECT_SERVICE_SNAPSHOT,
            snapshot_path.display()
        );
    }
    println!("  registry_table_bytes: {}", publication.table_bytes);
    println!("  registry_indices_bytes: {}", publication.indices_bytes);
    println!("  registry_gate_bytes: {}", publication.gate_bytes);
    println!(
        "  registry_state_manifest_bytes: {}",
        publication.state_manifest_bytes
    );
    Ok(())
}

fn run_lingqu_memory_record_artifact_access_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let event_id = required_cli_arg(args, "--event-id")?;
    let artifact_id = required_cli_arg(args, "--artifact-id")?;
    let access = parse_artifact_access_kind(&required_cli_arg(args, "--access")?)?;
    let run_id = required_cli_arg(args, "--run-id")?;
    let batch_id = required_cli_arg(args, "--batch-id")?;
    let actor = required_cli_arg(args, "--actor")?;
    let request_id = optional_cli_arg(args, "--request-id")?;
    let created_at_us = optional_cli_u64(args, "--created-at-us")?.unwrap_or(1);

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let mut memory_service = LingquMemoryService::new();
    rebuild_lingqu_memory_execution_registry_artifacts(&mut memory_service, &mut durable_store)
        .context("rebuild execution artifact registry")?;
    let artifact = memory_service
        .execution_artifact(&artifact_id)
        .cloned()
        .ok_or_else(|| anyhow::anyhow!("execution artifact `{artifact_id}` not found"))?;
    let event = ArtifactAccessRecord::new(
        event_id,
        artifact.artifact_id.clone(),
        access,
        artifact.kind,
        artifact.model.clone(),
        artifact.producer_boundary.clone(),
        run_id,
        batch_id,
        actor,
        request_id,
        artifact.checksum,
        1,
        created_at_us,
    )
    .map_err(|err| anyhow::anyhow!("build artifact access event: {err}"))?;
    memory_service
        .record_artifact_access(event.clone())
        .context("record artifact access event")?;
    memory_service
        .persist_artifact_access_to_dfs(&mut durable_store)
        .context("persist artifact access DFS audit")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: record-artifact-access");
    println!("  store_path: {}", store_path.display());
    println!(
        "  audit_path: {}",
        sim_memory::LINGQU_ARTIFACT_ACCESS_AUDIT_LOG_PATH
    );
    println!("  event_id: {}", event.event_id);
    println!("  artifact_id: {}", event.artifact_id);
    println!("  access: {:?}", event.access);
    println!("  artifact_kind: {:?}", event.artifact_kind);
    println!("  run_id: {}", event.run_id);
    println!("  batch_id: {}", event.batch_id);
    println!("  actor: {}", event.actor);
    println!("  artifact_checksum: {:#x}", event.artifact_checksum);
    println!("  checksum: {:#x}", event.checksum);
    Ok(())
}

fn run_lingqu_memory_boundary_request_from_w5_summary_cli(args: &[String]) -> anyhow::Result<()> {
    let summary_path = PathBuf::from(required_cli_arg(args, "--summary")?);
    let output_path = PathBuf::from(required_cli_arg(args, "--output")?);
    let step = required_cli_u64(args, "--step")?;
    let node = required_cli_arg(args, "--node")?;
    let position = required_cli_u64(args, "--position")?;
    let model = sim_memory::InferenceModelBinding {
        model_id: required_cli_arg(args, "--model-id")?,
        model_key: required_cli_arg(args, "--model-key")?,
        tokenizer_hash: required_cli_u64_auto(args, "--tokenizer-hash")?,
        profile_hash: required_cli_u64_auto(args, "--profile-hash")?,
    };
    let min_confidence_milli = optional_cli_u64(args, "--min-confidence-milli")?.unwrap_or(900);
    if min_confidence_milli > 1000 {
        anyhow::bail!("--min-confidence-milli must be in [0, 1000]");
    }
    let allowed_actions = parse_shortpath_actions(
        optional_cli_arg(args, "--allowed-actions")?
            .as_deref()
            .unwrap_or("jump-to-terminal"),
    )?;
    let created_at_us = optional_cli_u64(args, "--created-at-us")?.unwrap_or(1);
    let request_id = optional_cli_arg(args, "--request-id")?.unwrap_or_else(|| {
        format!(
            "boundary/{}/step{}/{}/position{}",
            model.model_key, step, node, position
        )
    });
    let engram_state_id = optional_cli_arg(args, "--engram-state-id")?;

    let summary = fs::read_to_string(&summary_path)
        .with_context(|| format!("read W5 summary {}", summary_path.display()))?;
    let observation = find_w5_boundary_observation(&summary, step, &node)
        .with_context(|| format!("find boundary observation step={step} node={node}"))?;
    let layer_start = required_summary_u32(&observation, "layer_start")?;
    let layer_end = required_summary_u32(&observation, "layer_end")?;
    let node_index = parse_node_index(&node)?;
    let target = required_summary_field(&observation, "target")?;
    let next_node_index = Some(parse_node_index(target)?);
    let hidden_key = required_summary_field(&observation, "hidden_key")?.to_string();
    let hidden_bytes = required_summary_u64(&observation, "hidden_bytes")?;
    let hidden_checksum = required_summary_u64_auto(&observation, "hidden_checksum")?;
    let hidden_version = required_summary_u64(&observation, "hidden_version")?;

    let request = BoundaryLookupRequest {
        request_id,
        model,
        boundary: sim_memory::RangeBoundary {
            phase: sim_memory::RangeBoundaryPhase::RangeExit,
            step_index: step,
            node_index,
            layer_start,
            layer_end,
            next_node_index,
            position,
        },
        hidden_state: sim_memory::HotTensorObjectRef {
            object_key: hidden_key.clone(),
            version: hidden_version,
            backend: sim_memory::HotObjectBackend::ObmmShmem,
            storage_ref: format!("obmm://{hidden_key}"),
            segment: None,
            offset: 0,
            bytes: hidden_bytes,
            checksum: hidden_checksum,
            dtype: sim_core::TensorDType::Opaque,
            shape: vec![hidden_bytes],
        },
        engram_state_id,
        min_confidence_milli: min_confidence_milli as u32,
        allowed_actions,
        created_at_us,
        match_mode: "exact".to_string(),
        min_match_score_milli: 1000,
    };
    request
        .validate()
        .map_err(|err| anyhow::anyhow!("validate boundary lookup request: {err}"))?;
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create boundary request dir {}", parent.display()))?;
    }
    fs::write(
        &output_path,
        serde_json::to_vec_pretty(&request).context("encode boundary lookup request")?,
    )
    .with_context(|| format!("write boundary lookup request {}", output_path.display()))?;
    println!("lingqu_memory_service");
    println!("  mode: boundary-request-from-w5-summary");
    println!("  summary: {}", summary_path.display());
    println!("  output: {}", output_path.display());
    println!("  request: {}", request.request_id);
    println!("  step: {}", request.boundary.step_index);
    println!("  node: {}", request.boundary.node_index);
    println!(
        "  layers: [{},{})",
        request.boundary.layer_start, request.boundary.layer_end
    );
    println!("  position: {}", request.boundary.position);
    println!("  hidden_key: {}", request.hidden_state.object_key);
    println!("  hidden_checksum: {:#x}", request.hidden_state.checksum);
    Ok(())
}

fn run_lingqu_memory_record_boundary_observations_from_w5_summary_cli(
    args: &[String],
) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let summary_path = PathBuf::from(required_cli_arg(args, "--summary")?);
    let step = required_cli_u64(args, "--step")?;
    let position = required_cli_u64(args, "--position")?;
    let created_at_us = optional_cli_u64(args, "--created-at-us")?.unwrap_or(1);
    let model = sim_memory::InferenceModelBinding {
        model_id: required_cli_arg(args, "--model-id")?,
        model_key: required_cli_arg(args, "--model-key")?,
        tokenizer_hash: required_cli_u64_auto(args, "--tokenizer-hash")?,
        profile_hash: required_cli_u64_auto(args, "--profile-hash")?,
    };
    model
        .validate()
        .map_err(|err| anyhow::anyhow!("validate model binding: {err}"))?;

    let summary = fs::read_to_string(&summary_path)
        .with_context(|| format!("read W5 summary {}", summary_path.display()))?;
    let run_id = optional_cli_arg(args, "--run-id")?
        .or_else(|| derive_w5_run_id_from_summary(&summary))
        .ok_or_else(|| anyhow::anyhow!("missing --run-id and summary run_dir is unavailable"))?;
    let observations = w5_boundary_observations_from_summary(
        &summary,
        &run_id,
        model,
        step,
        position,
        created_at_us,
    )?;
    if observations.is_empty() {
        anyhow::bail!("summary has no boundary observations for step={step}");
    }

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let mut memory_service = LingquMemoryService::new();
    for observation in observations {
        memory_service
            .register_boundary_observation(observation)
            .context("register boundary observation")?;
    }
    memory_service
        .persist_boundary_observations_to_dfs(&mut durable_store)
        .context("persist boundary observation DFS audit")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;
    let persisted = durable_store
        .load_boundary_observation_manifest()
        .context("reload boundary observation DFS audit")?;

    println!("lingqu_memory_service");
    println!("  mode: record-boundary-observations-from-w5-summary");
    println!("  store_path: {}", store_path.display());
    println!("  summary: {}", summary_path.display());
    println!(
        "  audit_log: {}",
        sim_memory::LINGQU_BOUNDARY_OBSERVATION_AUDIT_LOG_PATH
    );
    println!("  run_id: {run_id}");
    println!("  step: {step}");
    println!("  observations: {}", persisted.len());
    Ok(())
}

fn run_lingqu_memory_boundary_lookup_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let request_path = PathBuf::from(required_cli_arg(args, "--request")?);
    let response_path = PathBuf::from(required_cli_arg(args, "--response")?);
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);

    let (response, planner_decision) =
        run_w5_memory_boundary_lookup(&store_path, &request_path, now_us)?;
    let response_bytes =
        serde_json::to_vec_pretty(&response).context("encode boundary lookup response")?;
    if let Some(parent) = response_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create boundary lookup response dir {}", parent.display()))?;
    }
    fs::write(&response_path, response_bytes)
        .with_context(|| format!("write boundary lookup response {}", response_path.display()))?;
    println!("lingqu_memory_service");
    println!("  mode: boundary-lookup");
    println!("  store_path: {}", store_path.display());
    println!(
        "  manifest_path: {}",
        sim_memory::LINGQU_EXECUTION_ARTIFACT_MANIFEST_PATH
    );
    println!("  request_path: {}", request_path.display());
    println!("  response_path: {}", response_path.display());
    println!("  request: {}", response.request_id);
    println!("  support_id: {}", response.support.support_id);
    println!(
        "  supported_action: {:?}",
        response.support.supported_action
    );
    println!(
        "  supported_artifact: {}",
        response.support.artifact_id.as_deref().unwrap_or("")
    );
    println!(
        "  support_confidence_milli: {}",
        response.support.confidence_milli
    );
    println!(
        "  support_verify_required: {}",
        response.support.verify_required
    );
    println!(
        "  support_proof_checksum: {:#x}",
        response.support.proof_checksum
    );
    println!("  planner: w5_runtime_planner");
    println!("  planner_decision_id: {}", planner_decision.decision_id);
    println!("  planner_action: {:?}", planner_decision.action);
    println!(
        "  planner_proof_checksum: {:#x}",
        planner_decision.proof_checksum
    );
    Ok(())
}

fn run_lingqu_memory_boundary_lookup_from_observation_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let observation_id = required_cli_arg(args, "--observation-id")?;
    let response_path = PathBuf::from(required_cli_arg(args, "--response")?);
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);
    let min_confidence_milli = optional_cli_u64(args, "--min-confidence-milli")?.unwrap_or(900);
    if min_confidence_milli > 1000 {
        anyhow::bail!("--min-confidence-milli must be in [0, 1000]");
    }
    let allowed_actions = parse_shortpath_actions(
        optional_cli_arg(args, "--allowed-actions")?
            .as_deref()
            .unwrap_or("jump-to-terminal"),
    )?;
    let engram_state_id = optional_cli_arg(args, "--engram-state-id")?;

    let (response, planner_decision) = run_w5_memory_boundary_lookup_from_observation(
        &store_path,
        &observation_id,
        engram_state_id,
        min_confidence_milli as u32,
        allowed_actions,
        now_us,
        "exact".to_string(),
        1000,
        500,
        true,
    )?;
    let response_bytes =
        serde_json::to_vec_pretty(&response).context("encode boundary lookup response")?;
    if let Some(parent) = response_path.parent() {
        fs::create_dir_all(parent).with_context(|| {
            format!(
                "create boundary lookup observation response dir {}",
                parent.display()
            )
        })?;
    }
    fs::write(&response_path, response_bytes).with_context(|| {
        format!(
            "write boundary lookup observation response {}",
            response_path.display()
        )
    })?;

    println!("lingqu_memory_service");
    println!("  mode: boundary-lookup-from-observation");
    println!("  store_path: {}", store_path.display());
    println!("  observation_id: {observation_id}");
    println!("  response_path: {}", response_path.display());
    println!("  request: {}", response.request_id);
    println!("  support_id: {}", response.support.support_id);
    println!(
        "  supported_action: {:?}",
        response.support.supported_action
    );
    println!("  planner_decision_id: {}", planner_decision.decision_id);
    println!("  planner_action: {:?}", planner_decision.action);
    Ok(())
}

fn run_w5_memory_boundary_lookup(
    store_path: &Path,
    request_path: &Path,
    now_us: u64,
) -> anyhow::Result<(
    sim_memory::BoundaryLookupResponse,
    sim_memory::ShortpathDecisionRecord,
)> {
    let request_bytes = fs::read(request_path)
        .with_context(|| format!("read boundary lookup request {}", request_path.display()))?;
    let request = serde_json::from_slice::<BoundaryLookupRequest>(&request_bytes)
        .with_context(|| format!("decode boundary lookup request {}", request_path.display()))?;
    run_w5_memory_boundary_lookup_request(store_path, request, now_us)
}

fn run_w5_memory_boundary_lookup_from_observation(
    store_path: &Path,
    observation_id: &str,
    engram_state_id: Option<String>,
    min_confidence_milli: u32,
    allowed_actions: Vec<sim_memory::ShortpathAction>,
    now_us: u64,
    match_mode: String,
    min_match_score_milli: u32,
    min_terminal_margin_milli: u32,
    approximate_requires_verify: bool,
) -> anyhow::Result<(
    sim_memory::BoundaryLookupResponse,
    sim_memory::ShortpathDecisionRecord,
)> {
    let request = w5_memory_boundary_lookup_request_from_observation(
        store_path,
        observation_id,
        engram_state_id,
        min_confidence_milli,
        allowed_actions,
        now_us,
        match_mode,
        min_match_score_milli,
    )?;
    run_w5_memory_boundary_lookup_request_with_registry_requirement(
        store_path,
        request,
        now_us,
        true,
        None,
        min_terminal_margin_milli,
        approximate_requires_verify,
    )
}

fn w5_memory_boundary_lookup_request_from_observation(
    store_path: &Path,
    observation_id: &str,
    engram_state_id: Option<String>,
    min_confidence_milli: u32,
    allowed_actions: Vec<sim_memory::ShortpathAction>,
    now_us: u64,
    match_mode: String,
    min_match_score_milli: u32,
) -> anyhow::Result<BoundaryLookupRequest> {
    let mut durable_store = load_lingqu_memory_durable_store(store_path)?;
    let observations = durable_store
        .load_boundary_observation_manifest()
        .context("load boundary observation audit")?;
    let observation = observations
        .into_iter()
        .find(|candidate| candidate.observation_id == observation_id)
        .ok_or_else(|| anyhow::anyhow!("boundary observation not found: {observation_id}"))?;
    let request_id = format!("boundary-lookup/{observation_id}");
    let request_created_at_us = if now_us == 0 {
        observation.created_at_us
    } else {
        now_us
    };
    observation
        .to_lookup_request(
            request_id,
            engram_state_id,
            min_confidence_milli,
            allowed_actions,
            request_created_at_us,
            match_mode,
            min_match_score_milli,
        )
        .map_err(|err| anyhow::anyhow!("build lookup request from observation: {err}"))
}

struct ObjectServiceResolver<'a>(&'a LingquObjectServiceStub);

impl<'a> BoundaryPayloadResolver for ObjectServiceResolver<'a> {
    fn resolve_payload(&self, object_ref: &sim_memory::HotTensorObjectRef) -> Option<Vec<u8>> {
        self.0.get_copy(
            &object_ref.object_key,
            LingquObjectVersionSelector::Exact(object_ref.version),
        )
    }
}

fn w5_try_approximate_boundary_lookup(
    memory_service: &sim_memory::LingquMemoryService,
    request: &BoundaryLookupRequest,
    object_service: &LingquObjectServiceStub,
    min_match_score_milli: u32,
    min_terminal_margin_milli: u32,
    approximate_requires_verify: bool,
    now_us: u64,
) -> anyhow::Result<Option<sim_memory::ShortpathSupportRecord>> {
    let Some(decode_policy) = HiddenDecodePolicy::from_dtype(request.hidden_state.dtype) else {
        let support_id = format!("shortpath-support/approximate-miss/{}", request.request_id);
        return Ok(Some(sim_memory::ShortpathSupportRecord {
            support_id,
            request_id: request.request_id.clone(),
            supported_action: sim_memory::ShortpathAction::Continue,
            artifact_id: None,
            producer_position: Some(request.boundary.position),
            target_layer_start: None,
            target_layer_end: None,
            confidence_milli: 0,
            verify_required: false,
            proof_checksum: qwen3_checksum_words(&[
                1,
                w5_shortpath_action_tag(sim_memory::ShortpathAction::Continue),
                request.boundary.step_index,
                u64::from(request.boundary.node_index),
                u64::from(request.boundary.layer_start),
                u64::from(request.boundary.layer_end),
                request.boundary.position,
                request.hidden_state.checksum,
                request.hidden_state.bytes,
                now_us,
            ]),
            reason: "approximate_hidden_match_typed_payload_unavailable".to_string(),
            created_at_us: now_us,
            version: 1,
            match_score_milli: 0,
            match_metric: "".to_string(),
            match_mode: "approximate".to_string(),
            normalized_l2_milli: 0,
        }));
    };
    memory_service
        .approximate_boundary_lookup(
            request,
            &ObjectServiceResolver(object_service),
            decode_policy,
            min_match_score_milli,
            min_terminal_margin_milli,
            approximate_requires_verify,
            now_us,
        )
        .map_err(|e| anyhow::anyhow!(e))
}

fn run_w5_memory_boundary_lookup_request(
    store_path: &Path,
    request: BoundaryLookupRequest,
    now_us: u64,
) -> anyhow::Result<(
    sim_memory::BoundaryLookupResponse,
    sim_memory::ShortpathDecisionRecord,
)> {
    run_w5_memory_boundary_lookup_request_with_registry_requirement(
        store_path, request, now_us, true, None, 500, true,
    )
}

fn run_w5_memory_boundary_lookup_request_with_registry_requirement(
    store_path: &Path,
    request: BoundaryLookupRequest,
    now_us: u64,
    require_execution_manifest: bool,
    object_service: Option<&LingquObjectServiceStub>,
    min_terminal_margin_milli: u32,
    approximate_requires_verify: bool,
) -> anyhow::Result<(
    sim_memory::BoundaryLookupResponse,
    sim_memory::ShortpathDecisionRecord,
)> {
    let mut durable_store = load_lingqu_memory_durable_store(store_path)?;
    let effective_now_us = if now_us == 0 {
        request.created_at_us
    } else {
        now_us
    };

    let mut memory_service = LingquMemoryService::new();
    if require_execution_manifest {
        load_required_lingqu_memory_execution_registry_artifacts(
            &mut memory_service,
            &mut durable_store,
        )
        .context("load execution artifact manifest")?;
    } else {
        rebuild_lingqu_memory_execution_registry_artifacts(&mut memory_service, &mut durable_store)
            .context("rebuild execution artifact registry for runtime boundary lookup")?;
    }
    rebuild_lingqu_memory_shortpath_supports(&mut memory_service, &mut durable_store)
        .context("rebuild shortpath support audit")?;
    let mut response = memory_service
        .boundary_lookup(request.clone(), effective_now_us)
        .context("run boundary lookup")?;

    let match_mode = if request.match_mode.is_empty() {
        sim_memory::similarity::MatchMode::Exact
    } else {
        sim_memory::similarity::MatchMode::from_str(&request.match_mode)
            .unwrap_or(sim_memory::similarity::MatchMode::Exact)
    };

    if response.support.supported_action == sim_memory::ShortpathAction::Continue
        && object_service.is_some()
        && match_mode.allows_approximate()
    {
        if let Some(object_service) = object_service {
            let approximate_support = w5_try_approximate_boundary_lookup(
                &memory_service,
                &request,
                object_service,
                request.min_match_score_milli,
                min_terminal_margin_milli,
                approximate_requires_verify,
                effective_now_us,
            )
            .context("try approximate boundary lookup")?;
            if let Some(mut support) = approximate_support {
                support.created_at_us = effective_now_us;
                if support.supported_action != sim_memory::ShortpathAction::Continue {
                    response.artifact = memory_service
                        .execution_artifacts()
                        .get(support.artifact_id.as_deref().unwrap_or(""))
                        .cloned();
                }
                response.support = support;
            }
        }
    }

    let planner_decision = w5_plan_shortpath_decision_from_memory_support(&response)
        .context("plan W5 shortpath execution decision from Memory Service support")?;
    memory_service
        .persist_shortpath_supports_to_dfs(&mut durable_store)
        .context("persist shortpath support DFS audit")?;
    durable_store
        .persist_shortpath_decision_manifest(vec![planner_decision.clone()])
        .context("persist W5 planner shortpath decision DFS audit")?;
    save_lingqu_memory_durable_store(store_path, &durable_store)?;
    Ok((response, planner_decision))
}

fn run_w5_memory_boundary_lookup_request_in_memory(
    memory_service: &mut LingquMemoryService,
    request: BoundaryLookupRequest,
    object_service: Option<&LingquObjectServiceStub>,
    min_terminal_margin_milli: u32,
    approximate_requires_verify: bool,
) -> anyhow::Result<(
    sim_memory::BoundaryLookupResponse,
    sim_memory::ShortpathDecisionRecord,
)> {
    let match_mode = if request.match_mode.is_empty() {
        sim_memory::similarity::MatchMode::Exact
    } else {
        sim_memory::similarity::MatchMode::from_str(&request.match_mode)
            .unwrap_or(sim_memory::similarity::MatchMode::Exact)
    };
    let effective_now_us = request.created_at_us;
    let mut response = if match_mode == sim_memory::similarity::MatchMode::Approximate {
        let support_id = format!(
            "shortpath-support/approximate-request/{}",
            request.request_id
        );
        let proof_checksum = qwen3_checksum_words(&[
            2,
            w5_shortpath_action_tag(sim_memory::ShortpathAction::Continue),
            request.boundary.step_index,
            u64::from(request.boundary.node_index),
            u64::from(request.boundary.layer_start),
            u64::from(request.boundary.layer_end),
            request.boundary.position,
            request.hidden_state.checksum,
            request.hidden_state.bytes,
            effective_now_us,
        ]);
        sim_memory::BoundaryLookupResponse {
            request_id: request.request_id.clone(),
            support: sim_memory::ShortpathSupportRecord {
                support_id,
                request_id: request.request_id.clone(),
                supported_action: sim_memory::ShortpathAction::Continue,
                artifact_id: None,
                producer_position: Some(request.boundary.position),
                target_layer_start: None,
                target_layer_end: None,
                confidence_milli: 0,
                verify_required: false,
                proof_checksum,
                reason: "approximate_match_mode_skips_exact_lookup".to_string(),
                created_at_us: effective_now_us,
                version: 1,
                match_score_milli: 0,
                match_metric: "".to_string(),
                match_mode: "approximate".to_string(),
                normalized_l2_milli: 0,
            },
            artifact: None,
        }
    } else {
        memory_service
            .boundary_lookup(request.clone(), effective_now_us)
            .context("run in-memory boundary lookup")?
    };

    if response.support.supported_action == sim_memory::ShortpathAction::Continue
        && object_service.is_some()
        && match_mode.allows_approximate()
    {
        if let Some(object_service) = object_service {
            let approximate_support = w5_try_approximate_boundary_lookup(
                memory_service,
                &request,
                object_service,
                request.min_match_score_milli,
                min_terminal_margin_milli,
                approximate_requires_verify,
                effective_now_us,
            )
            .context("try in-memory approximate boundary lookup")?;
            if let Some(support) = approximate_support {
                if support.supported_action != sim_memory::ShortpathAction::Continue {
                    response.artifact = memory_service
                        .execution_artifacts()
                        .get(support.artifact_id.as_deref().unwrap_or(""))
                        .cloned();
                }
                response.support = support;
            }
        }
    }

    let planner_decision = w5_plan_shortpath_decision_from_memory_support(&response)
        .context("plan W5 shortpath execution decision from in-memory support")?;
    Ok((response, planner_decision))
}

#[derive(Debug, Clone, Eq, PartialEq)]
struct W5RuntimeBoundaryLookupReport {
    observation_count: usize,
    decision_count: usize,
    continue_count: usize,
    jump_to_layer_count: usize,
    jump_to_terminal_count: usize,
    require_verify_count: usize,
    first_decision_id: Option<String>,
    last_decision_id: Option<String>,
}

fn run_w5_runtime_boundary_lookups(
    store_path: &Path,
    observation_ids: &[String],
    now_us: u64,
    object_service: Option<&LingquObjectServiceStub>,
    match_mode: &str,
    min_match_score_milli: u32,
    min_terminal_margin_milli: u32,
    approximate_requires_verify: bool,
    min_source_confidence_milli: u32,
) -> anyhow::Result<W5RuntimeBoundaryLookupReport> {
    if observation_ids.is_empty() {
        anyhow::bail!("runtime boundary lookup requires at least one boundary observation");
    }

    let mut decisions = Vec::new();
    for observation_id in observation_ids {
        let request = w5_memory_boundary_lookup_request_from_observation(
            store_path,
            observation_id,
            None,
            min_source_confidence_milli,
            vec![sim_memory::ShortpathAction::JumpToTerminal],
            now_us,
            match_mode.to_string(),
            min_match_score_milli,
        )
        .with_context(|| {
            format!("build runtime boundary lookup request from observation {observation_id}")
        })?;
        let (_response, decision) =
            run_w5_memory_boundary_lookup_request_with_registry_requirement(
                store_path,
                request,
                now_us,
                false,
                object_service,
                min_terminal_margin_milli,
                approximate_requires_verify,
            )
            .with_context(|| {
                format!(
                    "run runtime Memory Service boundary lookup for observation {observation_id}"
                )
            })?;
        decisions.push(decision);
    }

    let mut report = W5RuntimeBoundaryLookupReport {
        observation_count: observation_ids.len(),
        decision_count: decisions.len(),
        continue_count: 0,
        jump_to_layer_count: 0,
        jump_to_terminal_count: 0,
        require_verify_count: 0,
        first_decision_id: decisions
            .first()
            .map(|decision| decision.decision_id.clone()),
        last_decision_id: decisions
            .last()
            .map(|decision| decision.decision_id.clone()),
    };
    for decision in decisions {
        match decision.action {
            sim_memory::ShortpathAction::Continue => report.continue_count += 1,
            sim_memory::ShortpathAction::JumpToLayer => report.jump_to_layer_count += 1,
            sim_memory::ShortpathAction::JumpToTerminal => report.jump_to_terminal_count += 1,
            sim_memory::ShortpathAction::RequireVerify => report.require_verify_count += 1,
        }
    }
    Ok(report)
}

fn run_lingqu_memory_plan_prefetch_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let request_path = PathBuf::from(required_cli_arg(args, "--request")?);
    let plan_path = PathBuf::from(required_cli_arg(args, "--plan")?);
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let request_bytes = fs::read(&request_path)
        .with_context(|| format!("read prefetch plan request {}", request_path.display()))?;
    let request = serde_json::from_slice::<PrefetchPlanRequest>(&request_bytes)
        .with_context(|| format!("decode prefetch plan request {}", request_path.display()))?;

    let mut memory_service = LingquMemoryService::new();
    load_required_lingqu_memory_execution_registry_artifacts(
        &mut memory_service,
        &mut durable_store,
    )
    .context("load execution artifact manifest")?;
    rebuild_lingqu_memory_prefetch_plans(&mut memory_service, &mut durable_store)
        .context("rebuild prefetch plan audit")?;
    let plan = memory_service
        .plan_prefetch(request, now_us)
        .context("plan prefetch")?;
    let plan_bytes = serde_json::to_vec_pretty(&plan).context("encode prefetch plan")?;
    if let Some(parent) = plan_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create prefetch plan dir {}", parent.display()))?;
    }
    fs::write(&plan_path, plan_bytes)
        .with_context(|| format!("write prefetch plan {}", plan_path.display()))?;
    memory_service
        .persist_prefetch_plans_to_dfs(&mut durable_store)
        .context("persist prefetch plan DFS audit")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: plan-prefetch");
    println!("  store_path: {}", store_path.display());
    println!(
        "  manifest_path: {}",
        sim_memory::LINGQU_EXECUTION_ARTIFACT_MANIFEST_PATH
    );
    println!("  request_path: {}", request_path.display());
    println!("  plan_path: {}", plan_path.display());
    println!("  plan: {}", plan.plan_id);
    println!("  scope: {:?}", plan.scope);
    println!("  target_step_index: {}", plan.target_step_index);
    println!("  target_position: {}", plan.target_position);
    println!(
        "  planned_artifacts: {}",
        plan.planned_artifact_ids.join(",")
    );
    println!("  checksum: {:#x}", plan.checksum);
    Ok(())
}

