#[derive(Debug, Clone, Default)]
struct W5PaperEngramEvalEvidence {
    decode_steps_summary_seen: bool,
    decode_steps_expected: u64,
    context_step_count: u64,
    context_count: u64,
    terminal_output_count: u64,
    hidden_checksum: u64,
    terminal_output_checksum: Option<u64>,
    row_prefetch_requests: u64,
    row_prefetch_hits: u64,
    max_backend_latency_us: u64,
    cpu_backend_output_match: Option<bool>,
}

#[derive(Debug, Clone, Eq, PartialEq, Ord, PartialOrd)]
struct W5PaperEngramContextBoundary {
    step: u64,
    node: u64,
    layers: String,
    total_layers: u64,
}

#[derive(Debug, Clone, Eq, PartialEq)]
struct W5PaperEngramContextBackendRecord {
    output_checksum: u64,
    row_prefetch_requests: u64,
    row_prefetch_hits: u64,
    latency_ms: u64,
}

#[derive(Debug, Clone, Default)]
struct W5PaperEngramContextBackendOutputs {
    cpu_reference: Option<W5PaperEngramContextBackendRecord>,
    simpler_host: Option<W5PaperEngramContextBackendRecord>,
}

fn w5_paper_engram_eval_evidence_from_summary(
    summary: &str,
) -> anyhow::Result<W5PaperEngramEvalEvidence> {
    let mut lines = std::collections::BTreeSet::new();
    for line in summary.lines() {
        lines.insert(line.to_string());
    }
    if let Some(run_dir) = w5_run_dir_from_summary(summary) {
        for entry in fs::read_dir(&run_dir)
            .with_context(|| format!("read W5 run dir {}", run_dir.display()))?
        {
            let path = entry?.path();
            let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
                continue;
            };
            if !name.ends_with("_guest.log") {
                continue;
            }
            let log = fs::read_to_string(&path)
                .with_context(|| format!("read W5 guest log {}", path.display()))?;
            for line in log.lines() {
                lines.insert(line.to_string());
            }
        }
    }

    let mut evidence = W5PaperEngramEvalEvidence::default();
    let mut terminal_output_by_step = std::collections::BTreeMap::<u64, u64>::new();
    let mut context_outputs = std::collections::BTreeMap::<
        W5PaperEngramContextBoundary,
        W5PaperEngramContextBackendOutputs,
    >::new();
    let mut backend_output_contradiction = false;
    for line in lines {
        if line.starts_with("summary: ") && line.contains("decode_steps_expected=") {
            let fields = parse_summary_fields(&line);
            evidence.decode_steps_summary_seen = true;
            evidence.decode_steps_expected =
                required_summary_u64(&fields, "decode_steps_expected")?;
        } else if line.contains("qwen3-engram-context:") {
            let fields = parse_summary_fields(&line);
            let mode = required_summary_field(&fields, "mode")?;
            if !mode.contains("paper") {
                continue;
            }
            let step = required_summary_u64(&fields, "step")?;
            let node = required_summary_u64(&fields, "node")?;
            let layers = required_summary_field(&fields, "layers")?;
            let total_layers = required_summary_u64(&fields, "total_layers")?;
            let output_checksum = required_summary_u64_auto(&fields, "output_checksum")?;
            let gate_checksum = required_summary_u64_auto(&fields, "gate_checksum")?;
            let index_checksum = required_summary_u64_auto(&fields, "index_checksum")?;
            let row_prefetch_hits = required_summary_u64(&fields, "row_prefetch_hits")?;
            let row_prefetch_requests = required_summary_u64(&fields, "row_prefetch_requests")?;
            let latency_ms = required_summary_u64(&fields, "latency_ms")?;
            if output_checksum == 0 || gate_checksum == 0 || index_checksum == 0 {
                anyhow::bail!("paper Engram context evidence has zero checksum");
            }
            if row_prefetch_hits > row_prefetch_requests {
                anyhow::bail!("paper Engram row prefetch hits exceed requests");
            }
            evidence.context_count += 1;
            let record = W5PaperEngramContextBackendRecord {
                output_checksum,
                row_prefetch_requests,
                row_prefetch_hits,
                latency_ms,
            };
            if mode == "simpler-host-paper-object-ref" {
                let entry = context_outputs
                    .entry(W5PaperEngramContextBoundary {
                        step,
                        node,
                        layers: layers.to_string(),
                        total_layers,
                    })
                    .or_default();
                if entry
                    .simpler_host
                    .replace(record)
                    .is_some_and(|previous| previous.output_checksum != output_checksum)
                {
                    backend_output_contradiction = true;
                }
            } else if mode == "cpu-reference-paper-object-ref" {
                let entry = context_outputs
                    .entry(W5PaperEngramContextBoundary {
                        step,
                        node,
                        layers: layers.to_string(),
                        total_layers,
                    })
                    .or_default();
                if entry
                    .cpu_reference
                    .replace(record)
                    .is_some_and(|previous| previous.output_checksum != output_checksum)
                {
                    backend_output_contradiction = true;
                }
            }
        } else if line.contains("stage qwen3_terminal_token_result_publish ") {
            let fields = parse_summary_fields(&line);
            let step = required_summary_u64(&fields, "step")?;
            let text_checksum = required_summary_u64_auto(&fields, "text_checksum")?;
            if text_checksum != 0 {
                terminal_output_by_step.insert(step, text_checksum);
            }
        } else if line.contains("stage qwen3_w5_terminal_logits_observation ") {
            let fields = parse_summary_fields(&line);
            if fields
                .get("source")
                .is_some_and(|source| source == "uapi_real_logits")
            {
                let step = required_summary_u64(&fields, "step")?;
                let text_checksum = required_summary_u64_auto(&fields, "text_checksum")?;
                if text_checksum != 0 {
                    terminal_output_by_step.insert(step, text_checksum);
                }
            }
        }
    }

    let mut backend_pair_count = 0u64;
    let mut backend_mismatch = backend_output_contradiction;
    let mut backend_context_steps = std::collections::BTreeSet::<u64>::new();
    for (boundary, outputs) in &context_outputs {
        if let (Some(cpu), Some(simpler)) = (&outputs.cpu_reference, &outputs.simpler_host) {
            backend_pair_count += 1;
            if cpu.output_checksum != simpler.output_checksum {
                backend_mismatch = true;
            }
        }
        if let Some(primary) = outputs.simpler_host.as_ref() {
            evidence.hidden_checksum =
                cli_mix_u64_checksum(evidence.hidden_checksum, boundary.step);
            evidence.hidden_checksum =
                cli_mix_u64_checksum(evidence.hidden_checksum, boundary.node);
            evidence.hidden_checksum =
                cli_mix_u64_checksum(evidence.hidden_checksum, primary.output_checksum);
            backend_context_steps.insert(boundary.step);
            evidence.row_prefetch_requests = evidence
                .row_prefetch_requests
                .saturating_add(primary.row_prefetch_requests);
            evidence.row_prefetch_hits = evidence
                .row_prefetch_hits
                .saturating_add(primary.row_prefetch_hits);
            evidence.max_backend_latency_us = evidence
                .max_backend_latency_us
                .max(primary.latency_ms.saturating_mul(1000));
        } else if let Some(cpu) = outputs.cpu_reference.as_ref() {
            evidence.hidden_checksum =
                cli_mix_u64_checksum(evidence.hidden_checksum, boundary.step);
            evidence.hidden_checksum =
                cli_mix_u64_checksum(evidence.hidden_checksum, boundary.node);
            evidence.hidden_checksum =
                cli_mix_u64_checksum(evidence.hidden_checksum, cpu.output_checksum);
        }
    }
    evidence.context_step_count = backend_context_steps.len() as u64;
    evidence.cpu_backend_output_match = if backend_mismatch {
        Some(false)
    } else if backend_pair_count > 0 {
        Some(true)
    } else {
        None
    };

    let mut terminal_checksum = 0u64;
    for (step, text_checksum) in &terminal_output_by_step {
        terminal_checksum = cli_mix_u64_checksum(terminal_checksum, *step);
        terminal_checksum = cli_mix_u64_checksum(terminal_checksum, *text_checksum);
    }
    evidence.terminal_output_count = terminal_output_by_step.len() as u64;
    evidence.terminal_output_checksum = (terminal_checksum != 0).then_some(terminal_checksum);
    Ok(evidence)
}

fn cli_mix_u64_checksum(current: u64, value: u64) -> u64 {
    let mixed = value
        .wrapping_add(0x9e37_79b9_7f4a_7c15)
        .wrapping_add(current << 6)
        .wrapping_add(current >> 2);
    current ^ mixed
}

fn run_lingqu_memory_register_terminal_logits_artifact_from_w5_summary_cli(
    args: &[String],
) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let summary_path = PathBuf::from(required_cli_arg(args, "--summary")?);
    let step = required_cli_u64(args, "--step")?;
    let node = required_cli_arg(args, "--node")?;
    let position = required_cli_u64(args, "--position")?;
    let confidence_milli = optional_cli_u64(args, "--confidence-milli")?.unwrap_or(980);
    if confidence_milli > 1000 {
        anyhow::bail!("--confidence-milli must be in [0, 1000]");
    }
    let created_at_us = optional_cli_u64(args, "--created-at-us")?.unwrap_or(1);
    let expires_at_us = optional_cli_u64(args, "--expires-at-us")?;
    let model = sim_memory::InferenceModelBinding {
        model_id: required_cli_arg(args, "--model-id")?,
        model_key: required_cli_arg(args, "--model-key")?,
        tokenizer_hash: required_cli_u64_auto(args, "--tokenizer-hash")?,
        profile_hash: required_cli_u64_auto(args, "--profile-hash")?,
    };
    model
        .validate()
        .map_err(|err| anyhow::anyhow!("validate model binding: {err}"))?;

    let summary = fs::read_to_string(&summary_path)
        .with_context(|| format!("read W5 summary {}", summary_path.display()))?;
    let run_id = derive_w5_run_id_from_summary(&summary)
        .ok_or_else(|| anyhow::anyhow!("missing W5 run id in {}", summary_path.display()))?;
    let observation = find_w5_boundary_observation(&summary, step, &node)
        .with_context(|| format!("find boundary observation step={step} node={node}"))?;
    let layer_start = required_summary_u32(&observation, "layer_start")?;
    let layer_end = required_summary_u32(&observation, "layer_end")?;
    let target = required_summary_field(&observation, "target")?;
    let hidden_key = required_summary_field(&observation, "hidden_key")?.to_string();
    let hidden_bytes = required_summary_u64(&observation, "hidden_bytes")?;
    let hidden_checksum = required_summary_u64_auto(&observation, "hidden_checksum")?;
    let hidden_version = required_summary_u64(&observation, "hidden_version")?;
    let terminal = find_w5_terminal_logits_observation(&summary, step)?;
    let payload = build_w5_terminal_logits_payload(step, &terminal)?;
    let payload_checksum = cli_bytes_checksum(&payload);
    let artifact_id = optional_cli_arg(args, "--artifact-id")?
        .unwrap_or_else(|| format!("artifact/logits/{run_id}/step{step}/{node}"));

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let payload_ref = durable_store
        .write_block_payload(
            format!("block/w5/terminal-logits/{run_id}/step{step}/{node}"),
            payload,
        )
        .context("write terminal logits artifact payload")?;
    let hidden_ref = sim_memory::HotTensorObjectRef {
        object_key: hidden_key.clone(),
        version: hidden_version,
        backend: sim_memory::HotObjectBackend::ObmmShmem,
        storage_ref: format!("obmm://{hidden_key}"),
        segment: None,
        offset: 0,
        bytes: hidden_bytes,
        checksum: hidden_checksum,
        dtype: sim_core::TensorDType::Opaque,
        shape: vec![hidden_bytes],
    };
    let artifact_checksum = cli_bytes_checksum(
        format!(
            "{}:{}:{}:{}:{}:{}:{payload_checksum:x}",
            artifact_id, run_id, step, node, layer_end, terminal.sampled_token
        )
        .as_bytes(),
    );
    let artifact = sim_memory::ExecutionArtifactObject {
        artifact_id: artifact_id.clone(),
        kind: sim_memory::ExecutionArtifactKind::Logits,
        model,
        producer_boundary: sim_memory::RangeBoundary {
            phase: sim_memory::RangeBoundaryPhase::RangeExit,
            step_index: step,
            node_index: parse_node_index(&node)?,
            layer_start,
            layer_end,
            next_node_index: Some(parse_node_index(target)?),
            position,
        },
        boundary_hidden_fingerprint: sim_memory::BoundaryTensorFingerprint::from_hot_ref(
            &hidden_ref,
        ),
        target_layer_start: layer_end,
        target_layer_end: layer_end,
        dtype: sim_core::TensorDType::Opaque,
        shape: vec![W5_TERMINAL_LOGITS_HEADER_BYTES as u64 + W5_TERMINAL_LOGITS_ENTRY_BYTES as u64],
        durable_payload_ref: Some(payload_ref),
        hot_object_ref: None,
        gsva_segment_ref: None,
        source_query_result_id: None,
        source_engram_state_id: None,
        confidence_milli: confidence_milli as u32,
        state: sim_memory::ExecutionArtifactState::Verified,
        checksum: artifact_checksum,
        version: 1,
        created_at_us,
        expires_at_us,
        terminal_logits_metadata: Some(sim_memory::TerminalLogitsMetadata {
            sampled_token: terminal.sampled_token,
            runner_up_token: terminal.runner_up_token,
            margin_milli: terminal.margin_milli,
            logits_checksum: terminal.logits_checksum,
            full_vocab_checked: terminal.full_vocab_checked,
        }),
    };
    artifact
        .validate()
        .map_err(|err| anyhow::anyhow!("validate terminal logits artifact: {err}"))?;

    let mut memory_service = LingquMemoryService::new();
    rebuild_lingqu_memory_execution_registry_artifacts(&mut memory_service, &mut durable_store)
        .context("rebuild execution artifact registry")?;
    validate_lingqu_execution_artifact_payloads(&mut durable_store, &artifact, "register")
        .context("validate terminal logits artifact payload")?;
    memory_service
        .register_execution_artifact(artifact.clone())
        .context("register terminal logits execution artifact")?;
    memory_service
        .persist_execution_artifacts_to_dfs(&mut durable_store)
        .context("persist execution artifact DFS manifest")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: register-terminal-logits-artifact-from-w5-summary");
    println!("  store_path: {}", store_path.display());
    println!("  summary: {}", summary_path.display());
    println!("  artifact: {}", artifact.artifact_id);
    println!("  step: {step}");
    println!("  node: {node}");
    println!("  layers: [{layer_start},{layer_end})");
    println!("  token: {}", terminal.sampled_token);
    println!("  logits_checksum: {:#x}", terminal.logits_checksum);
    println!("  payload_checksum: {payload_checksum:#x}");
    Ok(())
}

fn w5_kv_artifact_id(run_id: &str, step: u64, layer_start: u32, layer_end: u32) -> String {
    format!("artifact/kv/{run_id}/step{step}/layers-{layer_start}-{layer_end}")
}

fn run_lingqu_memory_promote_terminal_shortpath_artifacts_from_w5_summary_cli(
    args: &[String],
) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let summary_path = PathBuf::from(required_cli_arg(args, "--summary")?);
    let initial_position = optional_cli_u64(args, "--initial-position")?.unwrap_or(0);
    let step_count = optional_cli_u64(args, "--step-count")?;
    let node_filter = optional_cli_arg(args, "--nodes")?
        .map(|value| parse_nonempty_string_csv("--nodes", &value))
        .transpose()?
        .map(|nodes| nodes.into_iter().collect::<std::collections::BTreeSet<_>>());
    let confidence_milli = optional_cli_u64(args, "--confidence-milli")?.unwrap_or(980);
    if confidence_milli > 1000 {
        anyhow::bail!("--confidence-milli must be in [0, 1000]");
    }
    let min_confidence_milli = optional_cli_u64(args, "--min-confidence-milli")?.unwrap_or(900);
    if min_confidence_milli > 1000 {
        anyhow::bail!("--min-confidence-milli must be in [0, 1000]");
    }
    let created_at_us = optional_cli_u64(args, "--created-at-us")?.unwrap_or(1);
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(created_at_us);
    let expires_at_us = optional_cli_u64(args, "--expires-at-us")?;
    let engram_state_id = optional_cli_arg(args, "--engram-state-id")?;
    let object_registry_dir = optional_cli_arg(args, "--object-registry-dir")?.map(PathBuf::from);
    let object_store_path = optional_cli_arg(args, "--object-store")?.map(PathBuf::from);
    let model = sim_memory::InferenceModelBinding {
        model_id: required_cli_arg(args, "--model-id")?,
        model_key: required_cli_arg(args, "--model-key")?,
        tokenizer_hash: required_cli_u64_auto(args, "--tokenizer-hash")?,
        profile_hash: required_cli_u64_auto(args, "--profile-hash")?,
    };
    model
        .validate()
        .map_err(|err| anyhow::anyhow!("validate model binding: {err}"))?;

    let summary = fs::read_to_string(&summary_path)
        .with_context(|| format!("read W5 summary {}", summary_path.display()))?;
    let run_id = optional_cli_arg(args, "--run-id")?
        .or_else(|| derive_w5_run_id_from_summary(&summary))
        .ok_or_else(|| anyhow::anyhow!("missing --run-id and summary run_dir is unavailable"))?;
    let steps = w5_step_indices_from_summary(&summary, step_count)?;
    let step_filter = steps
        .iter()
        .copied()
        .collect::<std::collections::BTreeSet<_>>();
    let kv_exports = w5_kv_artifact_exports_from_summary(
        &summary,
        Some(&step_filter),
        object_registry_dir.as_deref(),
        object_store_path.as_deref(),
        initial_position,
    )?;

    let mut selected_observations = Vec::new();
    for step in &steps {
        let observations = w5_boundary_observations_from_summary(
            &summary,
            &run_id,
            model.clone(),
            *step,
            initial_position + *step,
            created_at_us,
        )?;
        if observations.is_empty() {
            anyhow::bail!("summary has no boundary observations for step={step}");
        }
        for observation in observations {
            if node_filter
                .as_ref()
                .is_some_and(|nodes| !nodes.contains(&observation.producer_node))
            {
                continue;
            }
            selected_observations.push(observation);
        }
    }
    if selected_observations.is_empty() {
        anyhow::bail!("no W5 boundary observations selected for promotion");
    }

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let existing_observations = match durable_store.load_boundary_observation_manifest() {
        Ok(observations) => observations,
        Err(sim_memory::LingquMemoryError::MissingDfsPath(_)) => Vec::new(),
        Err(err) => {
            return Err(err).context("load existing boundary observations before promotion");
        }
    };
    let existing_observation_ids = existing_observations
        .iter()
        .map(|observation| observation.observation_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    let mut memory_service = LingquMemoryService::new();
    let mut new_observation_count = 0usize;
    for observation in &selected_observations {
        if existing_observation_ids.contains(observation.observation_id.as_str()) {
            continue;
        }
        memory_service
            .register_boundary_observation(observation.clone())
            .context("register promoted boundary observation")?;
        new_observation_count += 1;
    }
    if new_observation_count > 0 {
        memory_service
            .persist_boundary_observations_to_dfs(&mut durable_store)
            .context("persist promoted boundary observation DFS audit")?;
    }
    rebuild_lingqu_memory_execution_registry_artifacts(&mut memory_service, &mut durable_store)
        .context("rebuild existing execution artifact registry")?;

    let mut promoted_artifact_ids = Vec::new();
    let mut promoted_tokens = Vec::new();
    for observation in &selected_observations {
        let terminal =
            find_w5_terminal_logits_observation(&summary, observation.boundary.step_index)
                .with_context(|| {
                    format!(
                        "find terminal logits for promoted observation {}",
                        observation.observation_id
                    )
                })?;
        let payload = build_w5_terminal_logits_payload(observation.boundary.step_index, &terminal)?;
        let payload_checksum = cli_bytes_checksum(&payload);
        let artifact_id = format!(
            "artifact/logits/{}/step{}/{}",
            run_id, observation.boundary.step_index, observation.producer_node
        );
        let payload_ref = durable_store
            .write_block_payload(
                format!(
                    "block/w5/terminal-logits/{}/step{}/{}",
                    run_id, observation.boundary.step_index, observation.producer_node
                ),
                payload,
            )
            .context("write promoted terminal logits artifact payload")?;
        let artifact_checksum = cli_bytes_checksum(
            format!(
                "{}:{}:{}:{}:{}:{}:{payload_checksum:x}",
                artifact_id,
                observation.run_id,
                observation.boundary.step_index,
                observation.producer_node,
                observation.boundary.layer_end,
                terminal.sampled_token
            )
            .as_bytes(),
        );
        let artifact = sim_memory::ExecutionArtifactObject {
            artifact_id: artifact_id.clone(),
            kind: sim_memory::ExecutionArtifactKind::Logits,
            model: observation.model.clone(),
            producer_boundary: observation.boundary.clone(),
            boundary_hidden_fingerprint: sim_memory::BoundaryTensorFingerprint::from_hot_ref(
                &observation.hidden_state,
            ),
            target_layer_start: observation.boundary.layer_end,
            target_layer_end: observation.boundary.layer_end,
            dtype: sim_core::TensorDType::Opaque,
            shape: vec![
                W5_TERMINAL_LOGITS_HEADER_BYTES as u64 + W5_TERMINAL_LOGITS_ENTRY_BYTES as u64,
            ],
            durable_payload_ref: Some(payload_ref),
            hot_object_ref: None,
            gsva_segment_ref: None,
            source_query_result_id: None,
            source_engram_state_id: None,
            confidence_milli: confidence_milli as u32,
            state: sim_memory::ExecutionArtifactState::Verified,
            checksum: artifact_checksum,
            version: 1,
            created_at_us,
            expires_at_us,
            terminal_logits_metadata: Some(sim_memory::TerminalLogitsMetadata {
                sampled_token: terminal.sampled_token,
                runner_up_token: terminal.runner_up_token,
                margin_milli: terminal.margin_milli,
                logits_checksum: terminal.logits_checksum,
                full_vocab_checked: terminal.full_vocab_checked,
            }),
        };
        artifact
            .validate()
            .map_err(|err| anyhow::anyhow!("validate promoted terminal logits artifact: {err}"))?;
        validate_lingqu_execution_artifact_payloads(&mut durable_store, &artifact, "promote")
            .context("validate promoted terminal logits artifact payload")?;
        memory_service
            .register_execution_artifact(artifact)
            .context("register promoted terminal logits execution artifact")?;
        promoted_artifact_ids.push(artifact_id);
        promoted_tokens.push(terminal.sampled_token);
    }
    let mut promoted_kv_artifact_ids = Vec::new();
    let mut promoted_kv_gsva_refs = 0usize;
    for export in &kv_exports {
        let artifact_id =
            w5_kv_artifact_id(&run_id, export.step, export.layer_start, export.layer_end);
        if export.gsva_segment_ref.is_some() {
            promoted_kv_gsva_refs += 1;
        }
        let payload_ref = if export.hot_object_ref.is_some() {
            None
        } else if let Some(payload_ref) = &export.payload_ref {
            Some(payload_ref.clone())
        } else {
            anyhow::bail!(
                "KV artifact export {} step={} node={} has no direct Object Service or registry ref",
                run_id,
                export.step,
                export.node
            );
        };
        let artifact_checksum = cli_bytes_checksum(
            format!(
                "{}:{}:{}:{}:{}:{}:{:x}",
                artifact_id,
                run_id,
                export.step,
                export.position,
                export.layer_start,
                export.layer_end,
                export.checksum
            )
            .as_bytes(),
        );
        let artifact = sim_memory::ExecutionArtifactObject {
            artifact_id: artifact_id.clone(),
            kind: sim_memory::ExecutionArtifactKind::KvCache,
            model: model.clone(),
            producer_boundary: sim_memory::RangeBoundary {
                phase: sim_memory::RangeBoundaryPhase::RangeExit,
                step_index: export.step,
                node_index: export.node_index,
                layer_start: export.layer_start,
                layer_end: export.layer_end,
                next_node_index: None,
                position: export.position,
            },
            boundary_hidden_fingerprint: sim_memory::BoundaryTensorFingerprint {
                bytes: export.hidden_bytes,
                checksum: export.hidden_checksum,
                dtype: sim_core::TensorDType::Opaque,
                shape: vec![export.hidden_bytes],
            },
            target_layer_start: export.layer_start,
            target_layer_end: export.layer_end,
            dtype: sim_core::TensorDType::Opaque,
            shape: vec![export.total_bytes],
            durable_payload_ref: payload_ref,
            hot_object_ref: export.hot_object_ref.clone(),
            gsva_segment_ref: export.gsva_segment_ref.clone(),
            source_query_result_id: None,
            source_engram_state_id: None,
            confidence_milli: confidence_milli as u32,
            state: sim_memory::ExecutionArtifactState::Verified,
            checksum: artifact_checksum,
            version: 1,
            created_at_us,
            expires_at_us,
            terminal_logits_metadata: None,
        };
        artifact
            .validate()
            .map_err(|err| anyhow::anyhow!("validate promoted KV artifact: {err}"))?;
        validate_lingqu_execution_artifact_payloads(&mut durable_store, &artifact, "promote-kv")
            .context("validate promoted KV artifact payload")?;
        memory_service
            .register_execution_artifact(artifact)
            .context("register promoted KV execution artifact")?;
        promoted_kv_artifact_ids.push(artifact_id);
    }
    memory_service
        .persist_execution_artifacts_to_dfs(&mut durable_store)
        .context("persist promoted execution artifact DFS manifest")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    let mut decision_ids = Vec::new();
    for observation in &selected_observations {
        let (_response, decision) = run_w5_memory_boundary_lookup_from_observation(
            &store_path,
            &observation.observation_id,
            engram_state_id.clone(),
            min_confidence_milli as u32,
            vec![sim_memory::ShortpathAction::JumpToTerminal],
            now_us,
            "exact".to_string(),
            1000,
            500,
            true,
        )
        .with_context(|| {
            format!(
                "promote boundary lookup from observation {}",
                observation.observation_id
            )
        })?;
        decision_ids.push(decision.decision_id);
    }

    println!("lingqu_memory_service");
    println!("  mode: promote-terminal-shortpath-artifacts-from-w5-summary");
    println!("  store_path: {}", store_path.display());
    println!("  summary: {}", summary_path.display());
    println!("  run_id: {run_id}");
    println!("  steps: {}", steps.len());
    println!("  observations: {}", selected_observations.len());
    println!("  artifacts: {}", promoted_artifact_ids.len());
    println!("  kv_artifacts: {}", promoted_kv_artifact_ids.len());
    println!("  kv_gsva_refs: {promoted_kv_gsva_refs}");
    println!("  decisions: {}", decision_ids.len());
    println!("  artifact_ids: {}", promoted_artifact_ids.join(","));
    println!("  kv_artifact_ids: {}", promoted_kv_artifact_ids.join(","));
    println!("  decision_ids: {}", decision_ids.join(","));
    println!(
        "  sampled_tokens: {}",
        promoted_tokens
            .into_iter()
            .map(|token| token.to_string())
            .collect::<Vec<_>>()
            .join(",")
    );
    Ok(())
}

fn run_lingqu_memory_register_prefix_cache_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let artifact_path = PathBuf::from(required_cli_arg(args, "--artifact")?);
    let artifact_bytes = fs::read(&artifact_path)
        .with_context(|| format!("read prefix cache artifact {}", artifact_path.display()))?;
    let artifact = serde_json::from_slice::<PrefixCacheArtifact>(&artifact_bytes)
        .with_context(|| format!("decode prefix cache artifact {}", artifact_path.display()))?;

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let mut memory_service = LingquMemoryService::new();
    let mut registry = rebuild_lingqu_memory_prefix_cache_registry_artifacts(
        &mut memory_service,
        &mut durable_store,
    )
    .context("rebuild prefix cache registry")?;
    validate_lingqu_prefix_cache_payloads(&mut durable_store, &artifact, "register")
        .context("validate prefix cache artifact payloads")?;
    memory_service
        .register_prefix_cache_artifact(artifact.clone())
        .context("register prefix cache artifact")?;

    registry
        .artifacts
        .retain(|entry| entry.artifact_id != artifact.artifact_id);
    registry.artifacts.push(artifact.clone());
    registry
        .artifacts
        .sort_by(|left, right| left.artifact_id.cmp(&right.artifact_id));
    memory_service
        .persist_prefix_cache_artifacts_to_dfs(&mut durable_store)
        .context("persist prefix cache DFS manifest")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: register-prefix-cache");
    println!("  store_path: {}", store_path.display());
    println!(
        "  manifest_path: {}",
        sim_memory::LINGQU_PREFIX_CACHE_MANIFEST_PATH
    );
    println!("  artifact_path: {}", artifact_path.display());
    println!("  artifact: {}", artifact.artifact_id);
    println!("  prefix_tokens: {}", artifact.key.prefix_token_count);
    println!(
        "  layer_range: {}..{}",
        artifact.key.layer_start, artifact.key.layer_end
    );
    println!("  confidence_milli: {}", artifact.confidence_milli);
    println!("  registry_artifacts: {}", registry.artifacts.len());
    Ok(())
}

fn run_lingqu_memory_restore_prefix_cache_ssd_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let report_path = optional_cli_arg(args, "--report")?.map(PathBuf::from);
    let store_json_bytes = fs::metadata(&store_path)
        .with_context(|| format!("stat durable store {}", store_path.display()))?
        .len();
    let store_sidecar_path = store_path.with_extension("bin");
    let store_sidecar_bytes = fs::metadata(&store_sidecar_path)
        .map(|metadata| metadata.len())
        .unwrap_or(0);

    let restore_started = Instant::now();
    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let report = durable_store
        .restore_prefix_cache_from_ssd_backend()
        .context("restore prefix cache from UB SSD host-file backend")?;
    let restore_ms = restore_started.elapsed().as_millis() as u64;

    let json_report = serde_json::json!({
        "backend": report.backend,
        "manifest_path": report.manifest_path,
        "store_path": store_path.display().to_string(),
        "store_json_bytes": store_json_bytes,
        "store_sidecar_bytes": store_sidecar_bytes,
        "restore_ms": restore_ms,
        "artifacts": report.artifacts,
        "ssd_backed_artifacts": report.ssd_backed_artifacts,
        "durable_payload_refs": report.durable_payload_refs,
        "durable_payload_bytes": report.durable_payload_bytes,
        "payload_proof_checksum": report.payload_proof_checksum,
        "status": "ok",
    });
    if let Some(report_path) = report_path {
        if let Some(parent) = report_path.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("create restore report dir {}", parent.display()))?;
        }
        fs::write(
            &report_path,
            serde_json::to_vec_pretty(&json_report).context("encode restore report")?,
        )
        .with_context(|| format!("write restore report {}", report_path.display()))?;
    }

    println!("lingqu_memory_service");
    println!("  mode: restore-prefix-cache-ssd");
    println!(
        "  backend: {}",
        json_report["backend"].as_str().unwrap_or("")
    );
    println!("  store_path: {}", store_path.display());
    println!(
        "  manifest_path: {}",
        sim_memory::LINGQU_PREFIX_CACHE_MANIFEST_PATH
    );
    println!("  store_json_bytes: {store_json_bytes}");
    println!("  store_sidecar_bytes: {store_sidecar_bytes}");
    println!("  restore_ms: {restore_ms}");
    println!(
        "  artifacts: {}",
        json_report["artifacts"].as_u64().unwrap_or(0)
    );
    println!(
        "  ssd_backed_artifacts: {}",
        json_report["ssd_backed_artifacts"].as_u64().unwrap_or(0)
    );
    println!(
        "  durable_payload_refs: {}",
        json_report["durable_payload_refs"].as_u64().unwrap_or(0)
    );
    println!(
        "  durable_payload_bytes: {}",
        json_report["durable_payload_bytes"].as_u64().unwrap_or(0)
    );
    println!(
        "  payload_proof_checksum: {:#x}",
        json_report["payload_proof_checksum"].as_u64().unwrap_or(0)
    );
    println!("  status: ok");
    Ok(())
}

fn run_lingqu_memory_lookup_prefix_cache_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let request_path = PathBuf::from(required_cli_arg(args, "--request")?);
    let response_path = PathBuf::from(required_cli_arg(args, "--response")?);
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let mut memory_service = LingquMemoryService::new();
    let _registry = load_required_lingqu_memory_prefix_cache_registry_artifacts(
        &mut memory_service,
        &mut durable_store,
    )
    .context("load prefix cache manifest")?;
    rebuild_lingqu_memory_prefix_cache_reuse_plans(&mut memory_service, &mut durable_store)
        .context("rebuild prefix cache reuse audit")?;
    let request_bytes = fs::read(&request_path).with_context(|| {
        format!(
            "read prefix cache lookup request {}",
            request_path.display()
        )
    })?;
    let request =
        serde_json::from_slice::<PrefixCacheLookupRequest>(&request_bytes).with_context(|| {
            format!(
                "decode prefix cache lookup request {}",
                request_path.display()
            )
        })?;

    let response = memory_service
        .lookup_prefix_cache(request, now_us)
        .context("lookup prefix cache")?;
    let response_bytes =
        serde_json::to_vec_pretty(&response).context("encode prefix cache lookup response")?;
    if let Some(parent) = response_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create prefix cache response dir {}", parent.display()))?;
    }
    fs::write(&response_path, response_bytes).with_context(|| {
        format!(
            "write prefix cache lookup response {}",
            response_path.display()
        )
    })?;
    memory_service
        .persist_prefix_cache_reuse_plans_to_dfs(&mut durable_store)
        .context("persist prefix cache reuse DFS audit")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: lookup-prefix-cache");
    println!("  store_path: {}", store_path.display());
    println!(
        "  manifest_path: {}",
        sim_memory::LINGQU_PREFIX_CACHE_MANIFEST_PATH
    );
    println!("  request_path: {}", request_path.display());
    println!("  response_path: {}", response_path.display());
    println!("  request: {}", response.request_id);
    println!("  action: {:?}", response.reuse_plan.action);
    println!(
        "  artifact: {}",
        response.reuse_plan.artifact_id.as_deref().unwrap_or("")
    );
    println!(
        "  matched_prefix_tokens: {}",
        response.reuse_plan.matched_prefix_token_count
    );
    println!("  verify_required: {}", response.reuse_plan.verify_required);
    println!(
        "  proof_checksum: {:#x}",
        response.reuse_plan.proof_checksum
    );
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LingquMemoryRpcServiceMode {
    MemoryService,
    PrefixCacheService,
}

impl LingquMemoryRpcServiceMode {
    fn service_name(self) -> &'static str {
        match self {
            LingquMemoryRpcServiceMode::MemoryService => "memory-service",
            LingquMemoryRpcServiceMode::PrefixCacheService => "prefix-cache-service",
        }
    }

    fn allows_boundary_lookup(self) -> bool {
        matches!(self, LingquMemoryRpcServiceMode::MemoryService)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "kebab-case")]
enum LingquMemoryRpcRequest {
    Health {
        request_id: String,
    },
    Shutdown {
        request_id: String,
    },
    BoundaryLookup {
        request_id: String,
        request: BoundaryLookupRequest,
        #[serde(default)]
        now_us: u64,
        #[serde(default = "default_rpc_min_terminal_margin_milli")]
        min_terminal_margin_milli: u32,
        #[serde(default = "default_rpc_approximate_requires_verify")]
        approximate_requires_verify: bool,
    },
    PrefixCacheRegister {
        request_id: String,
        artifact: PrefixCacheArtifact,
    },
    PrefixCacheLookup {
        request_id: String,
        request: PrefixCacheLookupRequest,
        #[serde(default)]
        now_us: u64,
    },
}

impl LingquMemoryRpcRequest {
    fn request_id(&self) -> &str {
        match self {
            LingquMemoryRpcRequest::Health { request_id }
            | LingquMemoryRpcRequest::Shutdown { request_id }
            | LingquMemoryRpcRequest::BoundaryLookup { request_id, .. }
            | LingquMemoryRpcRequest::PrefixCacheRegister { request_id, .. }
            | LingquMemoryRpcRequest::PrefixCacheLookup { request_id, .. } => request_id,
        }
    }

    fn is_shutdown(&self) -> bool {
        matches!(self, LingquMemoryRpcRequest::Shutdown { .. })
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct LingquMemoryRpcResponse {
    request_id: String,
    service: String,
    status: String,
    error: Option<String>,
    boundary_lookup: Option<sim_memory::BoundaryLookupResponse>,
    prefix_cache_lookup: Option<sim_memory::PrefixCacheLookupResponse>,
    prefix_cache_artifact_id: Option<String>,
    shutdown: bool,
}

impl LingquMemoryRpcResponse {
    fn ok(request_id: impl Into<String>, service: &str) -> Self {
        Self {
            request_id: request_id.into(),
            service: service.to_string(),
            status: "ok".to_string(),
            error: None,
            boundary_lookup: None,
            prefix_cache_lookup: None,
            prefix_cache_artifact_id: None,
            shutdown: false,
        }
    }

    fn err(request_id: impl Into<String>, service: &str, error: anyhow::Error) -> Self {
        Self {
            request_id: request_id.into(),
            service: service.to_string(),
            status: "error".to_string(),
            error: Some(format!("{error:#}")),
            boundary_lookup: None,
            prefix_cache_lookup: None,
            prefix_cache_artifact_id: None,
            shutdown: false,
        }
    }
}

fn default_rpc_min_terminal_margin_milli() -> u32 {
    500
}

fn default_rpc_approximate_requires_verify() -> bool {
    true
}

struct LingquMemoryRpcServer {
    service_mode: LingquMemoryRpcServiceMode,
    store_path: PathBuf,
    durable_store: LingquMemoryDurableStore,
    memory_service: LingquMemoryService,
    object_service: Option<LingquObjectServiceStub>,
}

impl LingquMemoryRpcServer {
    fn load(
        service_mode: LingquMemoryRpcServiceMode,
        store_path: PathBuf,
        object_store_path: Option<PathBuf>,
    ) -> anyhow::Result<Self> {
        let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
        let mut memory_service = LingquMemoryService::new();
        rebuild_lingqu_memory_execution_registry_artifacts(&mut memory_service, &mut durable_store)
            .context("rebuild execution artifact registry for RPC server")?;
        match memory_service.rebuild_boundary_observations_from_dfs(&mut durable_store) {
            Ok(_) | Err(sim_memory::LingquMemoryError::MissingDfsPath(_)) => {}
            Err(err) => {
                return Err(err).context("rebuild boundary observation registry for RPC server");
            }
        }
        rebuild_lingqu_memory_shortpath_supports(&mut memory_service, &mut durable_store)
            .context("rebuild shortpath support registry for RPC server")?;
        rebuild_lingqu_memory_prefix_cache_registry_artifacts(
            &mut memory_service,
            &mut durable_store,
        )
        .context("rebuild prefix cache registry for RPC server")?;
        rebuild_lingqu_memory_prefix_cache_reuse_plans(&mut memory_service, &mut durable_store)
            .context("rebuild prefix cache reuse audit for RPC server")?;

        let object_service = if let Some(object_store_path) = object_store_path {
            load_lingqu_object_service_snapshot(&object_store_path, &mut durable_store)?
                .map(LingquObjectServiceStub::import_snapshot)
                .transpose()
                .with_context(|| format!("import object store {}", object_store_path.display()))?
        } else {
            match durable_store.load_object_service_checkpoint() {
                Ok(snapshot) => Some(
                    LingquObjectServiceStub::import_snapshot(snapshot)
                        .context("import object service checkpoint from durable store")?,
                ),
                Err(sim_memory::LingquMemoryError::MissingDfsPath(_)) => None,
                Err(err) => return Err(err).context("load object service checkpoint"),
            }
        };

        Ok(Self {
            service_mode,
            store_path,
            durable_store,
            memory_service,
            object_service,
        })
    }

    fn service_name(&self) -> &'static str {
        self.service_mode.service_name()
    }

    fn handle_request(&mut self, request: LingquMemoryRpcRequest) -> LingquMemoryRpcResponse {
        let request_id = request.request_id().to_string();
        match self.try_handle_request(request) {
            Ok(response) => response,
            Err(err) => LingquMemoryRpcResponse::err(request_id, self.service_name(), err),
        }
    }

    fn try_handle_request(
        &mut self,
        request: LingquMemoryRpcRequest,
    ) -> anyhow::Result<LingquMemoryRpcResponse> {
        let service_name = self.service_name();
        match request {
            LingquMemoryRpcRequest::Health { request_id } => {
                Ok(LingquMemoryRpcResponse::ok(request_id, service_name))
            }
            LingquMemoryRpcRequest::Shutdown { request_id } => {
                let mut response = LingquMemoryRpcResponse::ok(request_id, service_name);
                response.shutdown = true;
                Ok(response)
            }
            LingquMemoryRpcRequest::BoundaryLookup {
                request_id,
                request,
                now_us,
                min_terminal_margin_milli,
                approximate_requires_verify,
            } => {
                if !self.service_mode.allows_boundary_lookup() {
                    anyhow::bail!("prefix-cache-service does not accept boundary-lookup RPC");
                }
                let effective_now_us = if now_us == 0 {
                    request.created_at_us
                } else {
                    now_us
                };
                let (mut response, planner_decision) =
                    run_w5_memory_boundary_lookup_request_in_memory(
                        &mut self.memory_service,
                        request,
                        self.object_service.as_ref(),
                        min_terminal_margin_milli,
                        approximate_requires_verify,
                    )
                    .context("run RPC boundary lookup")?;
                response.support.created_at_us = effective_now_us;
                self.memory_service
                    .persist_shortpath_supports_to_dfs(&mut self.durable_store)
                    .context("persist RPC shortpath support audit")?;
                self.durable_store
                    .persist_shortpath_decision_manifest(vec![planner_decision])
                    .context("persist RPC shortpath decision audit")?;
                save_lingqu_memory_durable_store(&self.store_path, &self.durable_store)?;
                let mut rpc_response = LingquMemoryRpcResponse::ok(request_id, service_name);
                rpc_response.boundary_lookup = Some(response);
                Ok(rpc_response)
            }
            LingquMemoryRpcRequest::PrefixCacheRegister {
                request_id,
                artifact,
            } => {
                validate_lingqu_prefix_cache_payloads(
                    &mut self.durable_store,
                    &artifact,
                    "rpc-register",
                )
                .context("validate RPC prefix cache artifact payloads")?;
                self.memory_service
                    .register_prefix_cache_artifact(artifact.clone())
                    .context("register RPC prefix cache artifact")?;
                self.memory_service
                    .persist_prefix_cache_artifacts_to_dfs(&mut self.durable_store)
                    .context("persist RPC prefix cache DFS manifest")?;
                save_lingqu_memory_durable_store(&self.store_path, &self.durable_store)?;
                let mut response = LingquMemoryRpcResponse::ok(request_id, service_name);
                response.prefix_cache_artifact_id = Some(artifact.artifact_id);
                Ok(response)
            }
            LingquMemoryRpcRequest::PrefixCacheLookup {
                request_id,
                request,
                now_us,
            } => {
                let effective_now_us = if now_us == 0 {
                    request.created_at_us
                } else {
                    now_us
                };
                let lookup_response = self
                    .memory_service
                    .lookup_prefix_cache(request, effective_now_us)
                    .context("run RPC prefix cache lookup")?;
                self.memory_service
                    .persist_prefix_cache_reuse_plans_to_dfs(&mut self.durable_store)
                    .context("persist RPC prefix cache reuse audit")?;
                save_lingqu_memory_durable_store(&self.store_path, &self.durable_store)?;
                let mut response = LingquMemoryRpcResponse::ok(request_id, service_name);
                response.prefix_cache_lookup = Some(lookup_response);
                Ok(response)
            }
        }
    }
}

fn run_lingqu_memory_rpc_server_cli(args: &[String]) -> anyhow::Result<()> {
    run_lingqu_memory_rpc_server_cli_with_mode(args, LingquMemoryRpcServiceMode::MemoryService)
}

fn run_lingqu_memory_prefix_cache_service_cli(args: &[String]) -> anyhow::Result<()> {
    run_lingqu_memory_rpc_server_cli_with_mode(args, LingquMemoryRpcServiceMode::PrefixCacheService)
}

fn run_lingqu_memory_rpc_server_cli_with_mode(
    args: &[String],
    service_mode: LingquMemoryRpcServiceMode,
) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let addr = optional_cli_arg(args, "--addr")?.unwrap_or_else(|| "127.0.0.1:0".to_string());
    let object_store_path = optional_cli_path(args, "--object-store")?;
    let ready_file = optional_cli_path(args, "--ready-file")?;
    let max_requests = optional_cli_u64(args, "--max-requests")?.map(|value| value as usize);

    let listener = TcpListener::bind(&addr).with_context(|| format!("bind RPC server {addr}"))?;
    let bound_addr = listener
        .local_addr()
        .context("read RPC server bound address")?;
    if let Some(ready_file) = ready_file {
        if let Some(parent) = ready_file.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("create RPC ready dir {}", parent.display()))?;
        }
        fs::write(&ready_file, bound_addr.to_string())
            .with_context(|| format!("write RPC ready file {}", ready_file.display()))?;
    }

    let server = LingquMemoryRpcServer::load(service_mode, store_path.clone(), object_store_path)?;
    println!("lingqu_memory_service");
    println!("  mode: {}", service_mode.service_name());
    println!("  store_path: {}", store_path.display());
    println!("  addr: {bound_addr}");
    println!(
        "  max_requests: {}",
        max_requests
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unbounded".to_string())
    );
    let served = lingqu_memory_rpc_serve(listener, server, max_requests)?;
    println!("  served_requests: {served}");
    Ok(())
}

fn run_lingqu_memory_rpc_client_cli(args: &[String]) -> anyhow::Result<()> {
    let addr = required_cli_arg(args, "--addr")?;
    let request_path = PathBuf::from(required_cli_arg(args, "--request")?);
    let response_path = PathBuf::from(required_cli_arg(args, "--response")?);
    let request_bytes = fs::read(&request_path)
        .with_context(|| format!("read RPC request {}", request_path.display()))?;
    let request = serde_json::from_slice::<LingquMemoryRpcRequest>(&request_bytes)
        .with_context(|| format!("decode RPC request {}", request_path.display()))?;
    let response = lingqu_memory_rpc_client_send(&addr, &request)
        .with_context(|| format!("send RPC request to {addr}"))?;
    if let Some(parent) = response_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create RPC response dir {}", parent.display()))?;
    }
    fs::write(
        &response_path,
        serde_json::to_vec_pretty(&response).context("encode RPC response")?,
    )
    .with_context(|| format!("write RPC response {}", response_path.display()))?;
    if response.status != "ok" {
        anyhow::bail!(
            "RPC request {} failed: {}",
            response.request_id,
            response
                .error
                .unwrap_or_else(|| "unknown error".to_string())
        );
    }
    println!("lingqu_memory_service");
    println!("  mode: rpc-client");
    println!("  addr: {addr}");
    println!("  request_path: {}", request_path.display());
    println!("  response_path: {}", response_path.display());
    println!("  request: {}", response.request_id);
    println!("  status: {}", response.status);
    Ok(())
}

fn lingqu_memory_rpc_serve(
    listener: TcpListener,
    mut server: LingquMemoryRpcServer,
    max_requests: Option<usize>,
) -> anyhow::Result<usize> {
    let mut served = 0usize;
    for stream in listener.incoming() {
        let stream = stream.context("accept RPC connection")?;
        let shutdown = lingqu_memory_rpc_handle_stream(stream, &mut server)
            .context("handle RPC connection")?;
        served += 1;
        if shutdown || max_requests.is_some_and(|limit| served >= limit) {
            break;
        }
    }
    Ok(served)
}

fn lingqu_memory_rpc_handle_stream(
    mut stream: TcpStream,
    server: &mut LingquMemoryRpcServer,
) -> anyhow::Result<bool> {
    let mut reader = BufReader::new(stream.try_clone().context("clone RPC stream")?);
    let mut line = String::new();
    let bytes = reader.read_line(&mut line).context("read RPC request")?;
    if bytes == 0 {
        anyhow::bail!("empty RPC request");
    }
    let request = serde_json::from_str::<LingquMemoryRpcRequest>(&line).context("decode RPC")?;
    let is_shutdown_request = request.is_shutdown();
    let response = server.handle_request(request);
    let response_bytes = serde_json::to_vec(&response).context("encode RPC response")?;
    stream
        .write_all(&response_bytes)
        .context("write RPC response")?;
    stream.write_all(b"\n").context("write RPC newline")?;
    stream.flush().context("flush RPC response")?;
    Ok(is_shutdown_request || response.shutdown)
}

fn lingqu_memory_rpc_client_send(
    addr: &str,
    request: &LingquMemoryRpcRequest,
) -> anyhow::Result<LingquMemoryRpcResponse> {
    let mut stream =
        TcpStream::connect(addr).with_context(|| format!("connect RPC server {addr}"))?;
    let request_bytes = serde_json::to_vec(request).context("encode RPC request")?;
    stream
        .write_all(&request_bytes)
        .context("write RPC request")?;
    stream.write_all(b"\n").context("write RPC newline")?;
    stream.flush().context("flush RPC request")?;
    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    let bytes = reader.read_line(&mut line).context("read RPC response")?;
    if bytes == 0 {
        anyhow::bail!("empty RPC response");
    }
    serde_json::from_str::<LingquMemoryRpcResponse>(&line).context("decode RPC response")
}

fn run_lingqu_memory_query_cli(args: &[String]) -> anyhow::Result<()> {
    let catalog_path = optional_cli_path(args, "--catalog")?;
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let query_embedding_path = PathBuf::from(required_cli_arg(args, "--query-embedding-json")?);
    let query_id = required_cli_arg(args, "--query-id")?;
    let top_k = required_cli_u32(args, "--top-k")?;
    let now_us = optional_cli_u64(args, "--now-us")?.unwrap_or(1);

    if top_k == 0 {
        anyhow::bail!("--top-k must be non-zero");
    }
    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let snapshot = load_required_lingqu_memory_catalog_snapshot_optional(
        args,
        catalog_path.as_deref(),
        &mut durable_store,
    )?;
    let query_embedding_bytes = fs::read(&query_embedding_path).with_context(|| {
        format!(
            "read query embedding json {}",
            query_embedding_path.display()
        )
    })?;
    let query_embedding =
        serde_json::from_slice::<LingquMemoryQueryEmbeddingInput>(&query_embedding_bytes)
            .with_context(|| {
                format!(
                    "decode query embedding json {}",
                    query_embedding_path.display()
                )
            })?;
    validate_lingqu_memory_query_embedding_input(&query_embedding)?;

    let query_payload = cli_f32_vec_to_le_bytes(&query_embedding.values);
    let query_block = optional_cli_arg(args, "--query-block")?
        .unwrap_or_else(|| format!("block/memory/query/{}", cli_path_id(&query_id)));
    let query_ref = durable_store
        .write_block_payload(query_block, query_payload)
        .context("write query embedding payload to Lingqu Block store")?;

    let mut memory_service = LingquMemoryService::new();
    memory_service
        .import_catalog_snapshot(snapshot.clone())
        .context("import catalog snapshot")?;
    let result = memory_service
        .query_memory_flat(
            &mut durable_store,
            MemoryQuery {
                query_id: query_id.clone(),
                corpus_ids: vec![snapshot.catalog.catalog_id.clone()],
                scope_filter: vec![MemoryScope::Project],
                visibility_filter: vec![MemoryVisibility::ProjectShared],
                min_trust: MemoryTrustLevel::UserConfirmed,
                min_confidence: 0.0,
                embedding_model_version: query_embedding.model_version.clone(),
                top_k: usize::try_from(top_k)
                    .map_err(|_| anyhow::anyhow!("--top-k exceeds usize"))?,
                query_embedding_ref: Some(query_ref.clone()),
            },
            now_us,
        )
        .context("query Lingqu memory flat index")?;
    let query_result_path = durable_store
        .persist_query_result(&result)
        .context("persist query result")?;
    save_lingqu_memory_durable_store(&store_path, &durable_store)?;

    println!("lingqu_memory_service");
    println!("  mode: query");
    println!("  catalog: {}", snapshot.catalog.catalog_id);
    println!(
        "  catalog_path: {}",
        cli_optional_path_display(catalog_path.as_deref())
    );
    println!("  store_path: {}", store_path.display());
    println!("  query_id: {query_id}");
    println!("  query_result: {}", result.result_id);
    println!("  query_result_manifest: {}", query_result_path.path);
    println!("  query_result_version: {}", result.version);
    println!("  query_result_checksum: {:#x}", result.checksum);
    println!(
        "  embedding_model_version: {}",
        query_embedding.model_version
    );
    println!("  query_embedding_block: {}", query_ref.block.0);
    println!("  query_embedding_bytes: {}", query_ref.bytes);
    println!("  query_embedding_checksum: {:#x}", query_ref.checksum);
    println!("  matches: {}", result.matches.len());
    println!(
        "  selected_records: {}",
        result.selected_record_ids.join(",")
    );
    println!("  selected_chunks: {}", result.selected_chunk_ids.join(","));
    if let Some(top) = result.matches.first() {
        println!("  top_record: {}", top.record_id);
        println!("  top_chunk: {}", top.chunk_id);
        println!("  top_score: {:.6}", top.score);
    }
    Ok(())
}

fn run_lingqu_memory_list_query_results_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let result_id_filter = optional_cli_arg(args, "--result-id")?;

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let results = durable_store
        .load_query_result_audit_manifest()
        .context("load query result audit")?;
    let filtered_results = results
        .iter()
        .filter(|result| {
            result_id_filter
                .as_ref()
                .map(|result_id| result.result_id == *result_id)
                .unwrap_or(true)
        })
        .collect::<Vec<_>>();
    if let Some(result_id) = result_id_filter.as_ref() {
        if filtered_results.is_empty() {
            anyhow::bail!("query result `{result_id}` not found in durable audit log");
        }
    }

    println!("lingqu_memory_service");
    println!("  mode: list-query-results");
    println!("  store_path: {}", store_path.display());
    println!(
        "  audit_path: {}",
        sim_memory::LINGQU_QUERY_RESULT_AUDIT_LOG_PATH
    );
    println!("  results: {}", filtered_results.len());
    for result in filtered_results {
        println!(
            "  result id={} query_id={} version={} checksum={:#x} matches={} selected_records={} selected_chunks={} created_at_us={}",
            result.result_id,
            result.query_id,
            result.version,
            result.checksum,
            result.matches.len(),
            result.selected_record_ids.join(","),
            result.selected_chunk_ids.join(","),
            result.created_at_us
        );
    }
    Ok(())
}

fn load_lingqu_memory_query_result_from_cli(
    args: &[String],
    durable_store: &mut LingquMemoryDurableStore,
) -> anyhow::Result<(LingquDfsPath, QueryResult)> {
    match (
        optional_cli_arg(args, "--query-result-id")?,
        optional_cli_arg(args, "--query-result-manifest")?,
    ) {
        (Some(result_id), None) => durable_store
            .load_query_result_by_id(&result_id)
            .with_context(|| format!("load query result `{result_id}` from durable DFS")),
        (None, Some(manifest)) => {
            let path = LingquDfsPath::new(manifest);
            let result = durable_store
                .load_query_result(&path)
                .context("load query result manifest")?;
            Ok((path, result))
        }
        (Some(_), Some(_)) => {
            anyhow::bail!("pass either --query-result-id or --query-result-manifest, not both")
        }
        (None, None) => {
            anyhow::bail!("missing required argument --query-result-id or --query-result-manifest")
        }
    }
}

fn run_lingqu_memory_list_boundary_observations_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let observation_id_filter = optional_cli_arg(args, "--observation-id")?;
    let run_id_filter = optional_cli_arg(args, "--run-id")?;
    let step_filter = optional_cli_u64(args, "--step")?;
    let node_filter = optional_cli_arg(args, "--node")?;

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let observations = durable_store
        .load_boundary_observation_manifest()
        .context("load boundary observation audit")?;
    let filtered_observations = observations
        .iter()
        .filter(|observation| {
            observation_id_filter
                .as_ref()
                .map(|observation_id| observation.observation_id == *observation_id)
                .unwrap_or(true)
        })
        .filter(|observation| {
            run_id_filter
                .as_ref()
                .map(|run_id| observation.run_id == *run_id)
                .unwrap_or(true)
        })
        .filter(|observation| {
            step_filter
                .map(|step| observation.boundary.step_index == step)
                .unwrap_or(true)
        })
        .filter(|observation| {
            node_filter
                .as_ref()
                .map(|node| observation.producer_node == *node)
                .unwrap_or(true)
        })
        .collect::<Vec<_>>();
    if let Some(observation_id) = observation_id_filter.as_ref() {
        if filtered_observations.is_empty() {
            anyhow::bail!("boundary observation `{observation_id}` not found in durable audit log");
        }
    }

    println!("lingqu_memory_service");
    println!("  mode: list-boundary-observations");
    println!("  store_path: {}", store_path.display());
    println!(
        "  audit_path: {}",
        sim_memory::LINGQU_BOUNDARY_OBSERVATION_AUDIT_LOG_PATH
    );
    println!("  observations: {}", filtered_observations.len());
    for observation in filtered_observations {
        println!(
            "  observation id={} run_id={} step={} node={} target={} layers=[{},{}] position={} hidden_key={} hidden_bytes={} hidden_checksum={:#x} source={} checksum={:#x} created_at_us={}",
            observation.observation_id,
            observation.run_id,
            observation.boundary.step_index,
            observation.producer_node,
            observation.consumer_node,
            observation.boundary.layer_start,
            observation.boundary.layer_end,
            observation.boundary.position,
            observation.hidden_state.object_key,
            observation.hidden_state.bytes,
            observation.hidden_state.checksum,
            observation.source,
            observation.checksum,
            observation.created_at_us
        );
    }
    Ok(())
}

fn run_lingqu_memory_list_execution_artifacts_cli(args: &[String]) -> anyhow::Result<()> {
    let store_path = PathBuf::from(required_cli_arg(args, "--store")?);
    let artifact_id_filter = optional_cli_arg(args, "--artifact-id")?;
    let kind_filter = optional_cli_arg(args, "--kind")?
        .map(|kind| parse_execution_artifact_kind_filter("--kind", &kind))
        .transpose()?;

    let mut durable_store = load_lingqu_memory_durable_store(&store_path)?;
    let artifacts = durable_store
        .load_execution_artifact_manifest()
        .context("load execution artifact manifest")?;
    let filtered_artifacts = artifacts
        .iter()
        .filter(|artifact| {
            artifact_id_filter
                .as_ref()
                .map(|artifact_id| artifact.artifact_id == *artifact_id)
                .unwrap_or(true)
        })
        .filter(|artifact| {
            kind_filter
                .map(|kind| artifact.kind == kind)
                .unwrap_or(true)
        })
        .collect::<Vec<_>>();
    if let Some(artifact_id) = artifact_id_filter.as_ref() {
        if filtered_artifacts.is_empty() {
            anyhow::bail!("execution artifact `{artifact_id}` not found in manifest");
        }
    }

    let logits = filtered_artifacts
        .iter()
        .filter(|artifact| artifact.kind == sim_memory::ExecutionArtifactKind::Logits)
        .count();
    let kv_cache = filtered_artifacts
        .iter()
        .filter(|artifact| artifact.kind == sim_memory::ExecutionArtifactKind::KvCache)
        .count();
    let hidden_state = filtered_artifacts
        .iter()
        .filter(|artifact| artifact.kind == sim_memory::ExecutionArtifactKind::HiddenState)
        .count();
    let kv_gsva_refs = filtered_artifacts
        .iter()
        .filter(|artifact| {
            artifact.kind == sim_memory::ExecutionArtifactKind::KvCache
                && artifact.gsva_segment_ref.is_some()
        })
        .count();

    println!("lingqu_memory_service");
    println!("  mode: list-execution-artifacts");
    println!("  store_path: {}", store_path.display());
    println!(
        "  manifest_path: {}",
        sim_memory::LINGQU_EXECUTION_ARTIFACT_MANIFEST_PATH
    );
    println!("  artifacts: {}", filtered_artifacts.len());
    println!("  logits: {logits}");
    println!("  kv_cache: {kv_cache}");
    println!("  kv_gsva_refs: {kv_gsva_refs}");
    println!("  hidden_state: {hidden_state}");
    for artifact in filtered_artifacts {
        let payload_bytes = artifact
            .durable_payload_ref
            .as_ref()
            .map(|payload_ref| payload_ref.bytes)
            .or_else(|| {
                artifact
                    .hot_object_ref
                    .as_ref()
                    .map(|hot_ref| hot_ref.bytes)
            })
            .or_else(|| {
                artifact
                    .gsva_segment_ref
                    .as_ref()
                    .map(|gsva_ref| gsva_ref.bytes)
            })
            .unwrap_or(0);
        let payload_ref = if artifact.durable_payload_ref.is_some() {
            "durable"
        } else if artifact.hot_object_ref.is_some() {
            "hot-object"
        } else if artifact.gsva_segment_ref.is_some() {
            "gsva"
        } else {
            "none"
        };
        let gsva_suffix = if let Some(gsva_ref) = artifact.gsva_segment_ref.as_ref() {
            format!(
                " gsva_segment_id={} gsva_bytes={} gsva_checksum={:#x}",
                gsva_ref.segment_id, gsva_ref.bytes, gsva_ref.checksum
            )
        } else {
            String::new()
        };
        println!(
            "  artifact id={} kind={} state={:?} step={} position={} node={} layers=[{},{}) payload_ref={} payload_bytes={} checksum={:#x}{}",
            artifact.artifact_id,
            w5_execution_artifact_kind_name(artifact.kind),
            artifact.state,
            artifact.producer_boundary.step_index,
            artifact.producer_boundary.position,
            artifact.producer_boundary.node_index,
            artifact.producer_boundary.layer_start,
            artifact.producer_boundary.layer_end,
            payload_ref,
            payload_bytes,
            artifact.checksum,
            gsva_suffix
        );
    }
    Ok(())
}

