    #[test]
    fn w5_object_service_snapshot_is_memory_backed_and_publish_is_idempotent() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_w5_object_service_memory_backed_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let object_store = root.join("object-store.json");
        let missing_object_store = root.join("missing-object-store.json");
        let mut durable_store = LingquMemoryDurableStore::new();
        let mut object_service =
            LingquObjectServiceStub::new(w5_memory_decision_publication_object_service_profile());
        let payload = vec![0x5a; 32];
        let key = "lingqu/memory/execution/artifact/logits/test/v1";

        let first = publish_w5_object_service_payload_ref(
            &mut object_service,
            QWEN3_DENSE_PROFILE_OBMM_KIND_TERMINAL_LOGITS,
            LingquObjectKind::Logits,
            1,
            2,
            key,
            &payload,
            "test",
        )
        .expect("publish first object");
        let second = publish_w5_object_service_payload_ref(
            &mut object_service,
            QWEN3_DENSE_PROFILE_OBMM_KIND_TERMINAL_LOGITS,
            LingquObjectKind::Logits,
            1,
            2,
            key,
            &payload,
            "test",
        )
        .expect("reuse identical object");
        assert_eq!(first.object_version, second.object_version);
        assert_eq!(object_service.export_snapshot().records.len(), 1);

        save_lingqu_object_service_snapshot(&object_store, &mut durable_store, &object_service)
            .expect("save object service snapshot");
        let restored =
            load_lingqu_object_service_snapshot(&missing_object_store, &mut durable_store)
                .expect("load object service checkpoint from Memory Service")
                .expect("checkpoint exists");
        let record = restored
            .records
            .iter()
            .find(|record| record.key == key)
            .expect("checkpoint record");
        assert_eq!(record.payload_bytes, payload);
        assert_eq!(record.version, first.object_version);
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn w5_object_service_payload_index_dedupes_identical_payload_versions() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_w5_object_service_payload_dedupe_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let object_store = root.join("object-store.json");
        let mut durable_store = LingquMemoryDurableStore::new();
        let mut object_service =
            LingquObjectServiceStub::new(w5_memory_decision_publication_object_service_profile());
        let payload = vec![0x7c; 64];
        let checksum = lingqu_object_payload_checksum(&payload);
        let key = "kvcache/qwen3-test/node1/layers-0-4/decode-step0";
        for _ in 0..2 {
            object_service
                .submit_publish(
                    LingquObjectPublishReq {
                        task: None,
                        key: key.to_string(),
                        kind: LingquObjectKind::KvCacheBlock,
                        producer_entity: 2,
                        owner_entity: Some(2),
                        expected_version: None,
                        metadata: LingquObjectMetadata {
                            bytes: payload.len() as u64,
                            checksum,
                            dtype: None,
                            shape: vec![payload.len() as u64],
                            layout: None,
                            expires_at_us: None,
                        },
                        placements: vec![LingquPayloadPlacement {
                            backend: LingquPayloadBackend::ObmmShmem,
                            storage_ref: format!("{key}/payload"),
                            segment: None,
                            offset: 0,
                            bytes: payload.len() as u64,
                            checksum,
                            locality: LingquObjectLocality::DomainShared(0),
                        }],
                        payload_bytes: payload.clone(),
                    },
                    1,
                )
                .expect("publish duplicate payload version");
        }

        save_lingqu_object_service_snapshot(&object_store, &mut durable_store, &object_service)
            .expect("save duplicate object service snapshot");
        let sidecar_len = fs::metadata(w5_object_service_payload_index_path(&object_store))
            .expect("object payload sidecar")
            .len() as usize;
        assert_eq!(
            sidecar_len,
            super::W5_OBJECT_SERVICE_PAYLOAD_INDEX_HEADER_BYTES
                + 2 * super::W5_OBJECT_SERVICE_PAYLOAD_INDEX_RECORD_BYTES
                + payload.len()
        );
        let restored = load_lingqu_object_service_snapshot_file(&object_store)
            .expect("load restored object store")
            .expect("object store exists");
        assert_eq!(restored.records.len(), 2);
        assert!(restored
            .records
            .iter()
            .all(|record| record.payload_bytes == payload));
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn lingqu_memory_durable_store_externalizes_large_block_payloads() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_lingqu_memory_external_blocks_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let store_path = root.join("store.json");
        let payload = vec![0x6b; 8 * 1024 * 1024 + 1];
        let mut durable_store = LingquMemoryDurableStore::new();
        let payload_ref = durable_store
            .write_block_payload("block/large/object-payload", payload.clone())
            .expect("write large block payload");

        save_lingqu_memory_durable_store(&store_path, &durable_store)
            .expect("save externalized durable store");

        let json_bytes = fs::metadata(&store_path).expect("stat durable json").len();
        let sidecar_path = store_path.with_extension("bin");
        let sidecar_bytes = fs::metadata(&sidecar_path)
            .expect("stat durable sidecar")
            .len();
        assert!(
            json_bytes < 1024 * 1024,
            "durable JSON should stay metadata-sized, got {json_bytes}"
        );
        assert_eq!(sidecar_bytes, payload.len() as u64);

        let mut restored =
            load_lingqu_memory_durable_store(&store_path).expect("load externalized store");
        assert_eq!(
            restored
                .read_block_payload(&payload_ref)
                .expect("read hydrated payload"),
            payload
        );
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn lingqu_memory_restores_prefix_cache_from_ssd_sidecar_and_rejects_corruption() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_lingqu_memory_prefix_cache_ssd_restore_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let store = root.join("store.json");
        let report_path = root.join("restore_report.json");
        let payload = vec![0x42; 8 * 1024 * 1024 + 1];
        let mut seed_store = LingquMemoryDurableStore::new();
        let prefix_payload_ref = seed_store
            .write_block_payload("block/prefix/ssd/8", payload.clone())
            .expect("write prefix cache payload");
        let key = sim_memory::PrefixCacheKey {
            model: sim_memory::InferenceModelBinding {
                model_id: "qwen3-test".to_string(),
                model_key: "qwen3-test-key".to_string(),
                tokenizer_hash: 0x1001,
                profile_hash: 0x2002,
            },
            namespace: "tenant/project/session".to_string(),
            chat_template_hash: 0x3003,
            prefix_token_hash: 0x4004,
            prefix_token_count: 8,
            rope_config_hash: 0x5005,
            kv_layout_hash: 0x6006,
            layer_start: 0,
            layer_end: 28,
            position_start: 0,
            position_end: 8,
            security_label: sim_memory::MemorySecurityLabel::Internal,
        };
        let artifact = sim_memory::PrefixCacheArtifact {
            artifact_id: "prefix-cache/ssd/8".to_string(),
            key,
            kv_artifact_ids: Vec::new(),
            durable_payload_refs: vec![prefix_payload_ref],
            hot_object_refs: Vec::new(),
            dtype: sim_core::TensorDType::F32,
            shape: vec![8, 4],
            confidence_milli: 950,
            state: sim_memory::ExecutionArtifactState::Verified,
            checksum: 0x2222_3333,
            version: 1,
            created_at_us: 10,
            expires_at_us: Some(100),
            last_used_at_us: 10,
            use_count: 1,
        };
        seed_store
            .persist_prefix_cache_manifest(vec![artifact])
            .expect("persist prefix cache manifest");
        save_lingqu_memory_durable_store(&store, &seed_store)
            .expect("save SSD-backed durable store");

        run_lingqu_memory_restore_prefix_cache_ssd_cli(&[
            "--store".to_string(),
            store.to_string_lossy().into_owned(),
            "--report".to_string(),
            report_path.to_string_lossy().into_owned(),
        ])
        .expect("restore prefix cache from SSD-backed store");
        let report_value: serde_json::Value =
            serde_json::from_slice(&fs::read(&report_path).expect("read restore report"))
                .expect("decode restore report");
        assert_eq!(report_value["backend"], "ub_ssd_host_file");
        assert_eq!(report_value["status"], "ok");
        assert_eq!(report_value["artifacts"], 1);
        assert_eq!(report_value["ssd_backed_artifacts"], 1);
        assert_eq!(report_value["durable_payload_refs"], 1);
        assert_eq!(report_value["durable_payload_bytes"], payload.len() as u64);
        assert!(report_value["store_json_bytes"].as_u64().unwrap() < 1024 * 1024);
        assert_eq!(
            report_value["store_sidecar_bytes"].as_u64().unwrap(),
            payload.len() as u64
        );

        let sidecar_path = store.with_extension("bin");
        let mut sidecar = fs::OpenOptions::new()
            .write(true)
            .open(&sidecar_path)
            .expect("open durable sidecar for corruption");
        sidecar
            .write_all(&[0x99])
            .expect("corrupt durable sidecar payload");
        let err = run_lingqu_memory_restore_prefix_cache_ssd_cli(&[
            "--store".to_string(),
            store.to_string_lossy().into_owned(),
        ])
        .expect_err("corrupt SSD-backed store must be rejected");
        let err_text = format!("{err:#}");
        assert!(
            err_text.contains("checksum mismatch")
                || err_text.contains("ChecksumMismatch")
                || err_text.contains("restore prefix cache")
        );
        let _ = fs::remove_dir_all(&root);
    }

