    #[test]
    fn w5_boundary_observation_recording_line_reports_skipped_without_ids() {
        let store = PathBuf::from("/tmp/w5-store.json");
        let summary = PathBuf::from("/tmp/w5-summary.txt");

        let line = w5_memory_boundary_observations_recorded_line(
            &store,
            &summary,
            &[],
            16,
            Some("shortpath_no_range_exit"),
        );

        assert_eq!(
            line,
            "  memory_boundary_observations_recorded: store=/tmp/w5-store.json summary=/tmp/w5-summary.txt records=0 expected_steps=16 status=skipped reason=shortpath_no_range_exit"
        );
        assert!(!line.contains("first_id="));
        assert!(!line.contains("last_id="));
    }

    #[test]
    fn w5_boundary_observation_recording_line_reports_ids_for_persisted_records() {
        let store = PathBuf::from("/tmp/w5-store.json");
        let summary = PathBuf::from("/tmp/w5-summary.txt");
        let ids = vec![
            "boundary-observation/run/step0/node1".to_string(),
            "boundary-observation/run/step1/node1".to_string(),
        ];

        let line = w5_memory_boundary_observations_recorded_line(&store, &summary, &ids, 2, None);

        assert_eq!(
            line,
            "  memory_boundary_observations_recorded: store=/tmp/w5-store.json summary=/tmp/w5-summary.txt records=2 expected_steps=2 first_id=boundary-observation/run/step0/node1 last_id=boundary-observation/run/step1/node1 status=ok"
        );
        assert!(!line.contains("reason="));
    }

    #[test]
    fn w5_runtime_records_boundary_observations_into_memory_store() {
        let root = std::env::temp_dir().join(format!(
            "ub_sim_w5_runtime_record_boundary_observations_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create temp dir");
        let weights_dir = root.join("Qwen3-0.6B");
        fs::create_dir_all(&weights_dir).expect("create weights dir");
        fs::write(
            weights_dir.join("config.json"),
            r#"{
                "_name_or_path": "Qwen/Qwen3-0.6B",
                "vocab_size": 151936,
                "hidden_size": 1024,
                "intermediate_size": 3072,
                "num_hidden_layers": 28,
                "num_attention_heads": 16,
                "num_key_value_heads": 8,
                "head_dim": 128,
                "max_position_embeddings": 40960,
                "rope_theta": 1000000
            }"#,
        )
        .expect("write config");
        fs::write(
            weights_dir.join("tokenizer.json"),
            br#"{"model":{"vocab":{}}}"#,
        )
        .expect("write tokenizer");
        fs::write(weights_dir.join("model.safetensors"), b"stub").expect("write weights");
        let args = Qwen3GuestDecodeLoopCliArgs {
            validate_only: false,
            step_count: 2,
            prompt: None,
            prompt_token_ids: None,
            script_path: PathBuf::from(
                "guest-linux/aarch64/scripts/run_llm_infer_eight_node_guest.sh",
            ),
            matmul_batch: None,
            model: None,
            weights_path: Some(weights_dir.clone()),
            w5_profile: None,
            sampler: Qwen3SamplerConfig::default(),
            engram: Qwen3EngramConfig::default(),
            memory_runtime_paths: None,
            memory_decisions: None,
            memory_observation_store_path: None,
            memory_runtime_boundary_lookup: false,
            memory_post_run_promote: false,
            memory_online_boundary_lookup: false,
            shortpath_match_mode: "exact".to_string(),
            min_match_score_milli: 850,
            min_terminal_margin_milli: 500,
            approximate_requires_verify: true,
            min_source_confidence_milli: 900,
        };
        let runtime = qwen3_guest_dense_runtime(&args).expect("dense runtime");
        let summary_path = root.join("w5_summary.txt");
        let store_path = root.join("store.json");
        fs::write(
            &summary_path,
            concat!(
                "summary: run_dir=/tmp/w5_runtime_run_headless8\n",
                "memory_boundary_observation: phase=range_exit step=0 node=node1 ",
                "observation_id=boundary-observation/w5_runtime_run/step0/node1 ",
                "target=node2 layers=[0,4) layer_start=0 layer_end=4 layer_count=4 ",
                "hidden_key=hidden/qwen3-0-6b/node2/range-runtime-input/decode-step0 ",
                "hidden_key_hash=0x0000000000001111 hidden_version=1 hidden_bytes=262144 ",
                "hidden_checksum=0x000000000000aaaa hidden_dtype=opaque hidden_shape=262144 ",
                "producer_publish_ms=100 producer_publish_mono_ms=20 backing=obmm_shmem ",
                "metadata=lingqu_object_service queue=obmm_spsc status=ok\n",
                "memory_boundary_observation: phase=range_exit step=1 node=node1 ",
                "observation_id=boundary-observation/w5_runtime_run/step1/node1 ",
                "target=node2 layers=[0,4) layer_start=0 layer_end=4 layer_count=4 ",
                "hidden_key=hidden/qwen3-0-6b/node2/range-runtime-input/decode-step1 ",
                "hidden_key_hash=0x0000000000002222 hidden_version=1 hidden_bytes=2048 ",
                "hidden_checksum=0x000000000000bbbb hidden_dtype=opaque hidden_shape=2048 ",
                "producer_publish_ms=200 producer_publish_mono_ms=30 backing=obmm_shmem ",
                "metadata=lingqu_object_service queue=obmm_spsc status=ok\n"
            ),
        )
        .expect("write summary");

        let recorded = record_w5_runtime_boundary_observations_from_summary(
            &store_path,
            &summary_path,
            &runtime,
            2,
            4,
            100,
        )
        .expect("record runtime observations");
        assert_eq!(
            recorded,
            vec![
                "boundary-observation/w5_runtime_run/step0/node1".to_string(),
                "boundary-observation/w5_runtime_run/step1/node1".to_string()
            ]
        );
        let mut durable =
            load_lingqu_memory_durable_store(&store_path).expect("reload durable store");
        let observations = durable
            .load_boundary_observation_manifest()
            .expect("load runtime observation audit");
        assert_eq!(observations.len(), 2);
        assert_eq!(observations[0].boundary.position, 4);
        assert_eq!(observations[1].boundary.position, 5);
        assert_eq!(observations[0].model.model_key, "qwen3-0-6b");
        assert_eq!(
            observations[0].model.tokenizer_hash,
            cli_bytes_checksum(br#"{"model":{"vocab":{}}}"#)
        );
        assert_eq!(observations[1].hidden_state.bytes, 2048);
        let recorded_again = record_w5_runtime_boundary_observations_from_summary(
            &store_path,
            &summary_path,
            &runtime,
            2,
            4,
            200,
        )
        .expect("record duplicate runtime observations idempotently");
        assert_eq!(recorded_again, recorded);
        let mut durable =
            load_lingqu_memory_durable_store(&store_path).expect("reload idempotent store");
        let observations = durable
            .load_boundary_observation_manifest()
            .expect("load idempotent runtime observation audit");
        assert_eq!(observations.len(), 2);
        let report = run_w5_runtime_boundary_lookups(
            &store_path,
            &recorded,
            120,
            None,
            "exact",
            1000,
            500,
            true,
            900,
        )
        .expect("run current-runtime boundary lookups");
        assert_eq!(report.observation_count, 2);
        assert_eq!(report.decision_count, 2);
        assert_eq!(report.continue_count, 2);
        assert_eq!(report.jump_to_terminal_count, 0);
        let mut durable =
            load_lingqu_memory_durable_store(&store_path).expect("reload runtime lookup store");
        let decisions = durable
            .load_shortpath_decision_manifest()
            .expect("load runtime lookup decisions");
        assert_eq!(decisions.len(), 2);
        assert!(decisions
            .iter()
            .all(|decision| decision.action == sim_memory::ShortpathAction::Continue));
        let supports = durable
            .load_shortpath_support_manifest()
            .expect("load runtime lookup supports");
        assert_eq!(supports.len(), 2);
        assert!(supports.iter().all(|support| {
            support.supported_action == sim_memory::ShortpathAction::Continue
                && support.artifact_id.is_none()
        }));
        let _ = fs::remove_dir_all(&root);
    }

