fn run_qwen3_tokenizer_projection_cli(
    args: &Qwen3TokenizerProjectionCliArgs,
) -> anyhow::Result<()> {
    let projection = build_tokenizer_projection_from_tokenizer_path(
        &args.tokenizer_path,
        args.merge_special_tokens,
    )
    .map_err(|err| {
        anyhow::anyhow!(
            "failed to build tokenizer projection from {}: {err}",
            args.tokenizer_path.display()
        )
    })?;
    if let Some(parent) = args.output_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("failed to create output dir {}", parent.display()))?;
    }
    fs::write(
        &args.output_path,
        serde_json::to_vec_pretty(&projection).context("failed to serialize projection")?,
    )
    .with_context(|| {
        format!(
            "failed to write tokenizer projection to {}",
            args.output_path.display()
        )
    })?;
    println!("projection written: {}", args.output_path.display());
    println!(
        "raw_tokens={} canonical_tokens={} special_tokens={} merged_pairs={} merge_special_tokens={}",
        projection.total_raw_tokens,
        projection.total_canonical_tokens,
        projection.total_special_tokens,
        projection.merged_token_count,
        projection.merge_special_tokens
    );
    Ok(())
}

fn run_deepseek_v4_flash_moe_report_cli(
    args: &DeepseekV4FlashMoeReportCliArgs,
) -> anyhow::Result<()> {
    let report = if let Some(catalog_path) = &args.weight_catalog_path {
        let Some(manifest_path) = &args.route_trace_manifest_path else {
            anyhow::bail!("--weight-catalog requires --route-trace-manifest");
        };
        deepseek_v4_flash_moe_decode_report_from_trace_manifest_file_with_catalog_file(
            manifest_path,
            catalog_path,
            args.cache_capacity_slots,
        )
        .map_err(anyhow::Error::msg)
        .with_context(|| {
            format!(
                "failed to run Flash MoE report from route trace manifest {} with weight catalog {}",
                manifest_path.display(),
                catalog_path.display()
            )
        })?
    } else if let Some(provider_path) = &args.weight_provider_path {
        if let Some(manifest_path) = &args.route_trace_manifest_path {
            deepseek_v4_flash_moe_decode_report_from_trace_manifest_file_with_provider_file(
                manifest_path,
                provider_path,
                args.cache_capacity_slots,
            )
            .map_err(anyhow::Error::msg)
            .with_context(|| {
                format!(
                    "failed to run Flash MoE report from route trace manifest {} with weight provider {}",
                    manifest_path.display(),
                    provider_path.display()
                )
            })?
        } else if let Some(trace_path) = &args.route_trace_path {
            deepseek_v4_flash_moe_decode_report_from_trace_file_with_provider_file(
                trace_path,
                provider_path,
                args.cache_capacity_slots,
            )
            .map_err(anyhow::Error::msg)
            .with_context(|| {
                format!(
                    "failed to run Flash MoE report from route trace {} with weight provider {}",
                    trace_path.display(),
                    provider_path.display()
                )
            })?
        } else {
            let provider =
                sim_models::deepseek_v4_flash_moe::parse_expert_weight_provider_spec_from_file(
                    provider_path,
                )
                .map_err(anyhow::Error::msg)
                .with_context(|| {
                    format!(
                        "failed to parse Flash weight provider {}",
                        provider_path.display()
                    )
                })?;
            deepseek_v4_flash_moe_decode_report_with_provider(
                args.step_count,
                args.tokens_per_step,
                args.cache_capacity_slots,
                &provider_path.display().to_string(),
                &provider,
            )
            .map_err(anyhow::Error::msg)
            .context("failed to run provider-backed Flash MoE report")?
        }
    } else if let Some(manifest_path) = &args.route_trace_manifest_path {
        deepseek_v4_flash_moe_decode_report_from_trace_manifest_file(
            manifest_path,
            args.cache_capacity_slots,
            args.expert_bytes,
        )
        .map_err(anyhow::Error::msg)
        .with_context(|| {
            format!(
                "failed to run Flash MoE report from route trace manifest {}",
                manifest_path.display()
            )
        })?
    } else if let Some(trace_path) = &args.route_trace_path {
        deepseek_v4_flash_moe_decode_report_from_trace_file(
            trace_path,
            args.cache_capacity_slots,
            args.expert_bytes,
        )
        .map_err(anyhow::Error::msg)
        .with_context(|| {
            format!(
                "failed to run Flash MoE report from route trace {}",
                trace_path.display()
            )
        })?
    } else {
        deepseek_v4_flash_moe_decode_report(
            args.step_count,
            args.tokens_per_step,
            args.cache_capacity_slots,
            args.expert_bytes,
        )
        .map_err(anyhow::Error::msg)
        .context("failed to run synthetic Flash MoE report")?
    };
    if let Some(expected) = &args.required_route_source_kind {
        if report.route_source_kind != *expected {
            anyhow::bail!(
                "Flash MoE route source kind mismatch: got={} expected={}",
                report.route_source_kind,
                expected
            );
        }
    }
    println!("deepseek_v4_flash_moe_report");
    println!(
        "  route_source: {} kind={}",
        report.route_source, report.route_source_kind
    );
    println!("  steps: {}", report.step_count);
    println!("  total_layers: {}", report.total_layers);
    println!("  tokens_per_step: {}", report.tokens_per_step);
    println!("  top_k: {}", report.top_k);
    println!(
        "  weight_provider: source={} model={} quant={}",
        report.weight_provider_source,
        report.weight_provider_model_key,
        report.weight_provider_quant
    );
    println!("  route_decisions: {}", report.route_decision_count);
    println!(
        "  weight_tiles: resolves={} unique={} payload_bytes={} checksum={:#x}",
        report.weight_tile_resolve_count,
        report.unique_weight_tile_count,
        report.weight_tile_payload_bytes,
        report.weight_tile_payload_checksum
    );
    println!(
        "  expert_cache: slots={} expert_bytes={} hits={} misses={} evictions={} pread_bytes={} hit_rate_milli={}",
        report.cache_capacity_slots,
        report.expert_bytes,
        report.hits,
        report.misses,
        report.evictions,
        report.pread_bytes,
        report.hit_rate_milli
    );
    println!(
        "  expert_latency: model=max(compute,miss_load) compute_time_us={} miss_load_time_us={} estimated_latency_us={} compute_us_per_touch={} load_bytes_per_us={}",
        report.compute_time_us,
        report.miss_load_time_us,
        report.estimated_latency_us,
        report.latency_compute_us_per_touch,
        report.latency_load_bytes_per_us
    );
    Ok(())
}

fn run_deepseek_v4_flash_route_trace_manifest_cli(
    args: &DeepseekV4FlashRouteTraceManifestCliArgs,
) -> anyhow::Result<()> {
    let trace_bytes = fs::read(&args.route_trace_path).with_context(|| {
        format!(
            "failed to read Flash route trace {}",
            args.route_trace_path.display()
        )
    })?;
    let trace_text = std::str::from_utf8(&trace_bytes).with_context(|| {
        format!(
            "Flash route trace is not valid UTF-8: {}",
            args.route_trace_path.display()
        )
    })?;
    let trace = sim_models::deepseek_v4_flash_moe::parse_expert_route_trace(trace_text)
        .map_err(anyhow::Error::msg)
        .with_context(|| {
            format!(
                "failed to parse Flash route trace {}",
                args.route_trace_path.display()
            )
        })?;
    let manifest_trace_path = args
        .manifest_trace_path
        .clone()
        .unwrap_or_else(|| args.route_trace_path.display().to_string());
    let trace_checksum =
        sim_models::deepseek_v4_flash_moe::expert_route_trace_checksum(&trace_bytes);
    let manifest = sim_models::deepseek_v4_flash_moe::infer_expert_route_trace_manifest(
        &trace,
        &args.source_kind,
        &manifest_trace_path,
        trace_checksum,
    )
    .map_err(anyhow::Error::msg)
    .context("failed to infer Flash route trace manifest")?;
    let manifest_text =
        sim_models::deepseek_v4_flash_moe::format_expert_route_trace_manifest(&manifest);
    if let Some(parent) = args.output_path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).with_context(|| {
                format!("failed to create manifest directory {}", parent.display())
            })?;
        }
    }
    fs::write(&args.output_path, manifest_text).with_context(|| {
        format!(
            "failed to write Flash route trace manifest {}",
            args.output_path.display()
        )
    })?;
    println!("deepseek_v4_flash_route_trace_manifest");
    println!("  output: {}", args.output_path.display());
    println!("  route_trace: {}", args.route_trace_path.display());
    println!("  source_kind: {}", manifest.source_kind);
    println!("  trace_checksum: 0x{:016x}", manifest.trace_checksum);
    println!("  steps: {}", manifest.step_count);
    println!("  total_layers: {}", manifest.total_layers);
    println!("  tokens_per_step: {}", manifest.tokens_per_step);
    println!("  top_k: {}", manifest.top_k);
    Ok(())
}

fn run_deepseek_v4_flash_weight_catalog_cli(
    args: &DeepseekV4FlashWeightCatalogCliArgs,
) -> anyhow::Result<()> {
    let catalog = if let Some(provider_path) = &args.provider_path {
        let provider =
            sim_models::deepseek_v4_flash_moe::parse_expert_weight_provider_spec_from_file(
                provider_path,
            )
            .map_err(anyhow::Error::msg)
            .with_context(|| {
                format!(
                    "failed to parse Flash weight provider {}",
                    provider_path.display()
                )
            })?;
        sim_models::deepseek_v4_flash_moe::expert_weight_catalog_from_provider_spec(
            &args.source_kind,
            &provider,
        )
        .map_err(anyhow::Error::msg)
        .with_context(|| {
            format!(
                "failed to build Flash weight catalog from provider {}",
                provider_path.display()
            )
        })?
    } else if let Some(payload_dir) = &args.payload_dir {
        sim_models::deepseek_v4_flash_moe::expert_weight_catalog_from_payload_dir(
            &args.source_kind,
            payload_dir,
            &args.payload_template,
            &args.quant,
        )
        .map_err(anyhow::Error::msg)
        .with_context(|| {
            format!(
                "failed to build Flash weight catalog from payload dir {}",
                payload_dir.display()
            )
        })?
    } else {
        anyhow::bail!("exactly one of --from-provider or --payload-dir is required");
    };

    let catalog_text = sim_models::deepseek_v4_flash_moe::format_expert_weight_catalog(&catalog)
        .map_err(anyhow::Error::msg)
        .context("failed to format Flash weight catalog")?;
    if let Some(parent) = args.output_path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).with_context(|| {
                format!("failed to create catalog directory {}", parent.display())
            })?;
        }
    }
    fs::write(&args.output_path, catalog_text).with_context(|| {
        format!(
            "failed to write Flash weight catalog {}",
            args.output_path.display()
        )
    })?;
    let written_catalog_text = fs::read_to_string(&args.output_path).with_context(|| {
        format!(
            "failed to read written Flash weight catalog {}",
            args.output_path.display()
        )
    })?;
    let reparsed =
        sim_models::deepseek_v4_flash_moe::parse_expert_weight_catalog(&written_catalog_text)
            .map_err(anyhow::Error::msg)
            .with_context(|| {
                format!(
                    "written Flash weight catalog failed validation: {}",
                    args.output_path.display()
                )
            })?;
    let payload_base = args
        .payload_dir
        .as_deref()
        .or_else(|| args.output_path.parent());
    sim_models::deepseek_v4_flash_moe::validate_expert_weight_catalog_payload_files(
        &reparsed,
        payload_base,
    )
    .map_err(anyhow::Error::msg)
    .with_context(|| {
        format!(
            "written Flash weight catalog payload validation failed: {}",
            args.output_path.display()
        )
    })?;
    let expert_bytes =
        sim_models::deepseek_v4_flash_moe::expert_weight_catalog_common_payload_bytes(&reparsed)
            .map_err(anyhow::Error::msg)
            .context("written Flash weight catalog uses unsupported mixed payload sizes")?;

    println!("deepseek_v4_flash_weight_catalog");
    println!("  output: {}", args.output_path.display());
    println!("  source_kind: {}", reparsed.source_kind);
    println!("  model: {}", reparsed.model_key);
    println!("  total_layers: {}", reparsed.total_layers);
    println!("  experts_per_layer: {}", reparsed.experts_per_layer);
    println!("  tiles: {}", reparsed.entries.len());
    println!("  expert_bytes: {}", expert_bytes);
    Ok(())
}

fn run_qwen3_decode_loop_cli(args: &Qwen3DecodeLoopCliArgs) -> anyhow::Result<()> {
    configure_simpler_dispatch_logging();
    let scenario_path = &args.scenario_path;
    let config = ScenarioConfig::from_yaml_file(scenario_path).with_context(|| {
        format!(
            "failed to load scenario config from {}",
            scenario_path.display()
        )
    })?;
    let topology = SimTopology::from_config(&config).context("failed to build topology")?;
    prepare_qwen3_decode_loop_environment(args)?;
    std::env::set_var("SIM_QWEN3_DECODE_PROGRESS", "1");
    eprintln!(
        "qwen3-decode-loop: scenario={} steps={} profile={} prompt_bytes={} matmul_batch={}",
        scenario_path.display(),
        args.step_count,
        args.profile,
        args.prompt.as_deref().map(str::len).unwrap_or(0),
        args.matmul_batch
            .map(|value| value.to_string())
            .unwrap_or_else(|| "default".to_string())
    );
    let report = model_decode_loop_report(
        &topology,
        args.step_count,
        &args.profile,
        args.prompt.as_deref(),
    )
    .map_err(anyhow::Error::msg)
    .context("failed to run decode loop")?;
    println!("qwen3_dense_reference_decode_loop");
    println!("  scenario: {}", scenario_path.display());
    println!("  steps: {}", report.steps.len());
    println!(
        "  final_guest_input_checksum: {:#x}",
        report.final_guest_input_checksum
    );
    println!("  decode_chain: {:#x}", report.decode_chain_checksum);
    println!(
        "  generated_text_lossy: {}",
        report.generated_text_lossy.escape_debug()
    );
    println!(
        "  generated_bytes: len={} checksum={:#x}",
        report.generated_byte_len, report.generated_byte_checksum
    );
    if matches!(
        args.profile.as_str(),
        "deepseek-v4-flash" | "deepseek_v4_flash"
    ) {
        let smoke = deepseek_v4_flash_geometry_smoke_report(&topology)
            .map_err(anyhow::Error::msg)
            .context("failed to run flash geometry smoke")?;
        println!("flash_geometry_smoke");
        println!(
            "  ready={} nodes={} layers={} hidden_range_bytes={} decode_hidden_bytes={} kv_state_bytes={} handoffs={} barriers={} weight_objects={} kv_objects={} hidden_objects={} desc_put={} desc_get={} checksum={:#x}",
            smoke.ready,
            smoke.node_count,
            smoke.layer_count,
            smoke.hidden_range_bytes,
            smoke.decode_hidden_bytes,
            smoke.total_kv_state_bytes,
            smoke.handoff_count,
            smoke.barrier_count,
            smoke.weight_object_count,
            smoke.kv_object_count,
            smoke.hidden_object_count,
            smoke.object_desc_put_count,
            smoke.object_desc_get_count,
            smoke.aggregate_checksum
        );
        for node in &smoke.nodes {
            println!(
                "  flash_node={} layers=[{},{}] count={} next={} terminal={} kv_state_bytes={} objects={} desc_put={} desc_get={} barrier={} handoff_ready={} checksum={:#x}",
                node.node_id,
                node.layer_start,
                node.layer_end,
                node.layer_count,
                node.next_node,
                node.terminal,
                node.kv_state_bytes,
                node.object_count,
                node.object_desc_put_count,
                node.object_desc_get_count,
                node.barrier_count,
                node.handoff_ready,
                node.node_checksum
            );
        }
    }
    match qwen3_decode_report_verbosity() {
        Qwen3DecodeReportVerbosity::Summary => {}
        Qwen3DecodeReportVerbosity::Steps => {
            for step in &report.steps {
                println!(
                    "  step={} runtime_prefill={} input_tokens={} sampled_tokens={} text_bytes={} contract_ready={} blockers={} synthetic_stages={} full_forward_math={} full_vocab_logits={} object_ready={} object_publish={} object_resolve={} object_append={} kv_resolve={} kv_append={} obmm_pool={} obmm_queue={} weight_payload_bytes={} weight_payload_slices={} weight_payload_complete={} weight_reconstructed_tensors={} weight_reconstructed_checksum={:#x} weight_payload_checksum={:#x} global_weight_objects={} global_weight_payload_bytes={} global_weight_tensors={} global_weight_checksum={:#x} object_checksum={:#x} input_checksum={:#x} next_input_checksum={:#x}",
                    step.step_index,
                    step.runtime_prefill_executed,
                    step.text_output.guest_input.prompt_token_count,
                    step.sampled_token_count,
                    step.text_output.byte_len,
                    step.real_inference_contract.ready,
                    step.real_inference_contract.blocker_count,
                    step.real_inference_contract.synthetic_stage_count,
                    step.real_inference_contract.full_forward_math,
                    step.real_inference_contract.full_vocab_logits,
                    step.object_service.ready,
                    step.object_service.publish_count,
                    step.object_service.resolve_count,
                    step.object_service.append_count,
                    step.object_service.kv_index_resolve_count,
                    step.object_service.kv_index_append_count,
                    step.object_service.obmm_pool_enabled,
                    step.object_service.obmm_pool_queue_submit_count,
                    step.object_service.weight_payload_bytes,
                    step.object_service.weight_payload_slice_count,
                    step.object_service.weight_payload_complete,
                    step.object_service.weight_reconstructed_tensor_count,
                    step.object_service.weight_reconstructed_tensor_checksum,
                    step.object_service.weight_payload_checksum,
                    step.object_service.global_weight_object_count,
                    step.object_service.global_weight_payload_bytes,
                    step.object_service.global_weight_tensor_count,
                    step.object_service.global_weight_payload_checksum,
                    step.object_service.object_checksum,
                    step.guest_input_checksum,
                    step.next_guest_input_checksum
                );
            }
        }
        Qwen3DecodeReportVerbosity::Verbose => {
            print_qwen3_decode_verbose_steps(&report.steps);
        }
    }
    Ok(())
}

fn run_qwen3_guest_decode_loop_cli(args: &Qwen3GuestDecodeLoopCliArgs) -> anyhow::Result<()> {
    let script_path = if args.script_path.is_absolute() {
        args.script_path.clone()
    } else {
        env::current_dir()
            .context("failed to read current directory")?
            .join(&args.script_path)
    };
    if !script_path.exists() {
        anyhow::bail!(
            "qwen3 guest decode script not found: {}",
            script_path.display()
        );
    }
    let runtime = qwen3_guest_dense_runtime(args)?;
    let mut effective_engram = args.engram.clone();
    let memory_publication = if !args.validate_only {
        if let Some(memory_runtime_paths) = &args.memory_runtime_paths {
            if w5_memory_runtime_paths_should_publish_engram_state(
                memory_runtime_paths,
                args.memory_decisions.is_some(),
                args.memory_runtime_boundary_lookup,
                args.engram.enabled,
            ) {
                ensure_w5_memory_engram_state(memory_runtime_paths, &runtime.profile)
                    .context("materialize W5 Memory Service engram state")?;
                let publication =
                    publish_w5_engram_state_ref_from_memory_objects(memory_runtime_paths)
                        .context("publish Memory Service EngramStateObjectRef for W5")?;
                effective_engram.enabled = true;
                effective_engram.pool = Qwen3EngramPool::Obmm;
                if effective_engram.context_op == Qwen3EngramContextOp::Disabled {
                    effective_engram.context_op = Qwen3EngramContextOp::CpuReference;
                }
                effective_engram.state_ref = Some(publication.state_ref_hex.clone());
                effective_engram.object_service_snapshot_path =
                    publication.object_service_snapshot_path.clone();
                Some(publication)
            } else {
                println!(
                "w5_memory_runtime_paths: mode=artifact_only engram_state={} reason=memory_decision_artifacts",
                memory_runtime_paths.engram_state_path.display()
            );
                None
            }
        } else {
            None
        }
    } else {
        None
    };
    let prompt_token_ids = args
        .prompt_token_ids
        .clone()
        .map(Ok)
        .or_else(|| {
            args.prompt
                .as_deref()
                .map(|prompt| qwen3_guest_prompt_token_ids_env(prompt, &runtime.weights_path))
        })
        .transpose()?
        .unwrap_or_default();
    let prompt_history_tokens = qwen3_parse_token_id_csv(&prompt_token_ids)?;
    let prefix_cache_lookup_now_us = cli_now_us();
    let prefix_cache_lookup_request = if let Some(memory_decision_config) = &args.memory_decisions {
        if memory_decision_config.prefix_cache_lookup
            && memory_decision_config.prefix_cache_reuse_plan_id.is_none()
        {
            w5_prefix_cache_lookup_request_for_prompt(
                &runtime,
                &prompt_history_tokens,
                prefix_cache_lookup_now_us,
            )?
        } else {
            None
        }
    } else {
        None
    };
    let memory_decisions = if let Some(memory_decision_config) = &args.memory_decisions {
        Some(
            load_w5_memory_decisions_from_store_with_prefix_lookup(
                memory_decision_config,
                prefix_cache_lookup_request,
                prefix_cache_lookup_now_us,
            )
            .context("load W5 execution decisions and Memory Service plans")?,
        )
    } else {
        None
    };
    let (guest_prompt_history_tokens, prefix_cache_replay_suffix_tokens) =
        w5_prefix_cache_guest_prompt_and_replay_suffix(
            &prompt_history_tokens,
            memory_decisions.as_ref(),
        )?;
    if !prefix_cache_replay_suffix_tokens.is_empty()
        && args.step_count <= prefix_cache_replay_suffix_tokens.len()
    {
        anyhow::bail!(
            "prefix-cache suffix replay requires steps > replay suffix tokens: steps={} replay_suffix_tokens={}",
            args.step_count,
            prefix_cache_replay_suffix_tokens.len()
        );
    }
    let guest_prompt_token_ids = if prefix_cache_replay_suffix_tokens.is_empty() {
        prompt_token_ids.clone()
    } else {
        qwen3_token_ids_csv(&guest_prompt_history_tokens)
    };
    let prefix_cache_replay_suffix_token_ids =
        qwen3_token_ids_csv(&prefix_cache_replay_suffix_tokens);
    let engram_simt = qwen3_prepare_engram_simt_mode(&effective_engram)?;
    let w5_profile =
        resolve_w5_inference_profile(args.w5_profile.as_deref(), &runtime, &effective_engram)?;
    if let (Some(config), Some(decisions)) = (&args.memory_decisions, &memory_decisions) {
        validate_w5_memory_decision_bundle_for_run(
            config,
            decisions,
            &runtime,
            w5_profile,
            &effective_engram,
            args.step_count,
        )
        .context("validate W5 Memory Service decisions for this run")?;
    }
    if args.validate_only {
        println!("qwen3_guest_decode_loop");
        println!("  validate_only: true");
        println!("  script: {}", script_path.display());
        println!("  workload: w5 inference cluster");
        println!("  w5_profile: {}", w5_profile.name);
        println!("  w5_profile_mode: {}", w5_profile.mode);
        println!("  w5_profile_nodes: {}", w5_profile.nodes);
        println!("  model_id: {}", runtime.profile.model_id);
        println!("  model_key: {}", runtime.model_key);
        println!("  weights_path: {}", runtime.weights_path.display());
        println!("  steps: {}", args.step_count);
        if let Some(engram_simt) = &engram_simt {
            println!(
                "  engram_simt_preflight: case={} passed={} failed={} total={} selected_case_passed={}",
                engram_simt.spec.case_name,
                engram_simt.preflight.passed_cases,
                engram_simt.preflight.failed_cases,
                engram_simt.preflight.total_cases,
                u8::from(engram_simt.preflight.selected_case_passed)
            );
        }
        if let Some(decisions) = &memory_decisions {
            let jump_to_terminal = decisions
                .shortpath_entries
                .iter()
                .filter(|entry| {
                    entry.decision.action == sim_memory::ShortpathAction::JumpToTerminal
                })
                .count();
            let artifact_count = decisions
                .shortpath_entries
                .iter()
                .filter(|entry| entry.artifact.is_some())
                .count();
            println!(
                "  memory_decision_validation: entries={} jump_to_terminal={} artifact_count={}",
                decisions.shortpath_entries.len(),
                jump_to_terminal,
                artifact_count
            );
        } else {
            println!("  memory_decision_validation: entries=0");
        }
        return Ok(());
    }
    let memory_decision_publication = if let Some(decisions) = &memory_decisions {
        if w5_memory_decisions_reference_artifacts(decisions) {
            let memory_runtime_paths = args.memory_runtime_paths.as_ref().ok_or_else(|| {
                anyhow::anyhow!(
                    "W5 artifact-backed decisions and Memory Service plans require --memory-store, --memory-object-store, --memory-engram-state, and --memory-registry-dir so artifacts can be published as object refs"
                )
            })?;
            let artifact_store_path = args
                .memory_decisions
                .as_ref()
                .map(|config| config.store_path.as_path())
                .unwrap_or_else(|| memory_runtime_paths.store_path.as_path());
            Some(
                publish_w5_memory_decision_artifact_refs(
                    memory_runtime_paths,
                    artifact_store_path,
                    args.memory_decisions
                        .as_ref()
                        .and_then(|config| config.artifact_object_store_path.as_deref()),
                    decisions,
                )
                .context("publish W5 execution artifact object refs")?,
            )
        } else {
            None
        }
    } else {
        None
    };
    if let Some(publication) = &memory_decision_publication {
        if let Some(snapshot_path) = &publication.object_service_snapshot_path {
            effective_engram.object_service_snapshot_path = Some(snapshot_path.clone());
        }
    }
    let engram_registry_validation =
        qwen3_validate_guest_engram_state_registry(&effective_engram, &runtime.profile)?;
    println!("qwen3_guest_decode_loop");
    println!("  script: {}", script_path.display());
    println!("  workload: w5 inference cluster");
    println!("  w5_profile: {}", w5_profile.name);
    println!("  w5_profile_mode: {}", w5_profile.mode);
    println!("  w5_profile_nodes: {}", w5_profile.nodes);
    println!("  w5_profile_backend: {}", w5_profile.backend_profile);
    println!(
        "  w5_profile_engram_required: {}",
        w5_profile.engram_required
    );
    println!("  model_id: {}", runtime.profile.model_id);
    println!("  model_key: {}", runtime.model_key);
    println!("  weights_path: {}", runtime.weights_path.display());
    println!(
        "  hidden_range_bytes: {}",
        hidden_range_bytes(&runtime.profile)
    );
    println!(
        "  decode_hidden_bytes: {}",
        decode_hidden_bytes(&runtime.profile)
    );
    println!("  steps: {}", args.step_count);
    println!(
        "  sampler: policy=top_k_top_p_temperature top_k={} top_p_milli={} temperature_milli={} seed={}",
        args.sampler.top_k,
        args.sampler.top_p_milli,
        args.sampler.temperature_milli,
        args.sampler.seed
    );
    if let Some(prompt) = &args.prompt {
        println!("  prompt_bytes: {}", prompt.len());
    }
    if let Some(matmul_batch) = args.matmul_batch {
        prepare_qwen3_matmul_batch_environment(matmul_batch)?;
        println!("  matmul_batch: {}", matmul_batch);
    }
    if let Some(publication) = &memory_publication {
        println!("  memory_service: lingqu_memory_service");
        println!("  memory_fixture_backed: false");
        println!("  memory_engram_state: {}", publication.engram_state_id);
        println!(
            "  memory_object_service_snapshot: {}",
            effective_engram
                .object_service_snapshot_path
                .as_ref()
                .map(|path| path.display().to_string())
                .unwrap_or_default()
        );
        println!("  memory_engram_state_ref: {}", publication.state_ref_hex);
        println!("  memory_context_table_bytes: {}", publication.table_bytes);
        println!(
            "  memory_context_indices_bytes: {}",
            publication.indices_bytes
        );
        println!("  memory_context_gate_bytes: {}", publication.gate_bytes);
        println!(
            "  memory_context_state_manifest_bytes: {}",
            publication.state_manifest_bytes
        );
    }
    if let Some(decisions) = &memory_decisions {
        println!("  w5_planner: w5_runtime_planner");
        if decisions.shortpath_entries.len() > 1 {
            let first = decisions
                .shortpath_entries
                .first()
                .expect("nonempty entries");
            let last = decisions
                .shortpath_entries
                .last()
                .expect("nonempty entries");
            let jump_to_terminal = decisions
                .shortpath_entries
                .iter()
                .filter(|entry| {
                    entry.decision.action == sim_memory::ShortpathAction::JumpToTerminal
                })
                .count();
            let artifact_count = decisions
                .shortpath_entries
                .iter()
                .filter(|entry| entry.artifact.is_some())
                .count();
            println!(
                "  w5_shortpath_registry: entries={} jump_to_terminal={} artifact_count={} first_decision_id={} last_decision_id={}",
                decisions.shortpath_entries.len(),
                jump_to_terminal,
                artifact_count,
                first.decision.decision_id,
                last.decision.decision_id
            );
        } else if let Some(decision) = &decisions.shortpath {
            println!(
                "  w5_shortpath_decision: id={} support_id={} action={} artifact_id={} artifact_kind={} artifact_checksum={} proof_checksum={:#x}",
                decision.decision_id,
                decision.support_id.as_deref().unwrap_or(""),
                w5_shortpath_action_name(decision.action),
                decision.artifact_id.as_deref().unwrap_or(""),
                decisions
                    .shortpath_artifact
                    .as_ref()
                    .map(|artifact| w5_execution_artifact_kind_name(artifact.kind))
                    .unwrap_or("none"),
                decisions
                    .shortpath_artifact
                    .as_ref()
                    .map(|artifact| format!("{:#x}", artifact.checksum))
                    .unwrap_or_else(|| "none".to_string()),
                decision.proof_checksum
            );
        }
        if let Some(plan) = &decisions.prefetch {
            println!(
                "  memory_prefetch_plan: id={} scope={} target_step_index={} artifact_count={} checksum={:#x}",
                plan.plan_id,
                w5_prefetch_scope_name(plan.scope),
                plan.target_step_index,
                decisions.prefetch_artifacts.len(),
                plan.checksum
            );
        }
        if let Some(plan) = &decisions.prefix_cache {
            println!(
                "  memory_prefix_cache_reuse_plan: id={} action={} artifact_id={} matched_prefix_tokens={} artifact_checksum={} proof_checksum={:#x}",
                plan.plan_id,
                w5_prefix_cache_reuse_action_name(plan.action),
                plan.artifact_id.as_deref().unwrap_or(""),
                plan.matched_prefix_token_count,
                decisions
                    .prefix_cache_artifact
                    .as_ref()
                    .map(|artifact| format!("{:#x}", artifact.checksum))
                    .unwrap_or_else(|| "none".to_string()),
                plan.proof_checksum
            );
            if !prefix_cache_replay_suffix_tokens.is_empty() {
                println!(
                    "  memory_prefix_cache_suffix_replay: initial_prompt_tokens={} replay_suffix_tokens={} status=enabled",
                    guest_prompt_history_tokens.len(),
                    prefix_cache_replay_suffix_tokens.len()
                );
            }
        }
    }
    if let Some(publication) = &memory_decision_publication {
        if let Some(snapshot_path) = &publication.object_service_snapshot_path {
            println!(
                "  memory_artifact_object_service_snapshot: {}",
                snapshot_path.display()
            );
        }
        if publication.shortpath_refs.len() > 1 {
            let total_payload_bytes = publication
                .shortpath_refs
                .iter()
                .map(|published| published.payload_bytes)
                .sum::<usize>();
            let payload_checksum_xor = publication
                .shortpath_refs
                .iter()
                .fold(0u64, |acc, published| acc ^ published.payload_checksum);
            let first_id = publication
                .shortpath_refs
                .first()
                .map(|published| published.artifact_id.as_str())
                .unwrap_or("");
            let last_id = publication
                .shortpath_refs
                .last()
                .map(|published| published.artifact_id.as_str())
                .unwrap_or("");
            println!(
                "  memory_shortpath_artifact_refs: count={} first_id={} last_id={} total_payload_bytes={} payload_checksum_xor={:#x}",
                publication.shortpath_refs.len(),
                first_id,
                last_id,
                total_payload_bytes,
                payload_checksum_xor
            );
        } else if let Some(published) = &publication.shortpath_ref {
            println!(
                "  memory_shortpath_artifact_ref: id={} payload_bytes={} payload_checksum={:#x}",
                published.artifact_id, published.payload_bytes, published.payload_checksum
            );
        }
        if let Some(registry_ref) = &publication.shortpath_registry_ref {
            println!(
                "  memory_shortpath_registry_ref: entries={} payload_bytes={} payload_checksum={:#x}",
                publication.shortpath_refs.len(),
                registry_ref.payload_bytes,
                registry_ref.payload_checksum
            );
        }
        if !publication.shortpath_kv_refs.is_empty() {
            let total_payload_bytes = publication
                .shortpath_kv_refs
                .iter()
                .map(|published| published.payload_bytes)
                .sum::<usize>();
            let payload_checksum_xor = publication
                .shortpath_kv_refs
                .iter()
                .fold(0u64, |acc, published| acc ^ published.payload_checksum);
            let first_id = publication
                .shortpath_kv_refs
                .first()
                .map(|published| published.artifact_id.as_str())
                .unwrap_or("");
            let last_id = publication
                .shortpath_kv_refs
                .last()
                .map(|published| published.artifact_id.as_str())
                .unwrap_or("");
            println!(
                "  memory_shortpath_kv_artifact_refs: count={} first_id={} last_id={} total_payload_bytes={} payload_checksum_xor={:#x}",
                publication.shortpath_kv_refs.len(),
                first_id,
                last_id,
                total_payload_bytes,
                payload_checksum_xor
            );
        }
        if !publication.prefetch_refs.is_empty() {
            let total_payload_bytes = publication
                .prefetch_refs
                .iter()
                .map(|published| published.payload_bytes)
                .sum::<usize>();
            let payload_checksum_xor = publication
                .prefetch_refs
                .iter()
                .fold(0u64, |acc, published| acc ^ published.payload_checksum);
            let first_id = publication
                .prefetch_refs
                .first()
                .map(|published| published.artifact_id.as_str())
                .unwrap_or("");
            let last_id = publication
                .prefetch_refs
                .last()
                .map(|published| published.artifact_id.as_str())
                .unwrap_or("");
            println!(
                "  memory_prefetch_artifact_refs: count={} first_id={} last_id={} total_payload_bytes={} payload_checksum_xor={:#x}",
                publication.prefetch_refs.len(),
                first_id,
                last_id,
                total_payload_bytes,
                payload_checksum_xor
            );
        }
        if let Some(published) = &publication.prefix_cache_ref {
            println!(
                "  memory_prefix_cache_artifact_ref: id={} payload_bytes={} payload_checksum={:#x}",
                published.artifact_id, published.payload_bytes, published.payload_checksum
            );
        }
    }
    if effective_engram.enabled {
        println!(
            "  engram: enabled=true mode={} pool={} owner_node={} no_repeat_ngram_size={} repetition_penalty_milli={} history_window={} blocked_token_ids={:?} context_op={} report={}",
            qwen3_engram_mode_name(effective_engram.mode),
            qwen3_engram_pool_name(effective_engram.pool),
            effective_engram.owner_node,
            effective_engram.no_repeat_ngram_size,
            effective_engram.repetition_penalty_milli,
            effective_engram.history_window,
            effective_engram.blocked_token_ids,
            qwen3_engram_context_op_name(effective_engram.context_op),
            qwen3_engram_report_name(effective_engram.report)
        );
        if let Some(spec) = &engram_simt {
            let preflight = &spec.preflight;
            let spec = &spec.spec;
            println!(
                "  engram_simt: artifact_dir={} symbol={} case={} run_mode={} soc_version={} preflight_passed={} preflight_failed={} preflight_total={}",
                spec.binary_path
                    .parent()
                    .map(Path::display)
                    .map(|display| display.to_string())
                    .unwrap_or_else(|| "<unknown>".to_string()),
                spec.symbol,
                spec.case_name,
                spec.run_mode,
                spec.soc_version,
                preflight.passed_cases,
                preflight.failed_cases,
                preflight.total_cases
            );
        }
        if let Some(validation) = &engram_registry_validation {
            println!(
                "  engram_state_registry: hidden_size={} table_rows={} table_bytes={} indices_bytes={} gate_weight_bytes={}",
                validation.hidden_size,
                validation.table_rows,
                validation.table_bytes,
                validation.indices_bytes,
                validation.gate_weight_bytes
            );
        }
    }
    println!("  worker_path: 8-node W5 inference cluster OBMM object-service range forward");
    let trace_file = qwen3_guest_trace_file_path(env::var_os("TRACE_FILE"), std::process::id());
    if let Some(parent) = trace_file.parent() {
        fs::create_dir_all(parent).with_context(|| {
            format!(
                "failed to create qwen3 guest trace directory {}",
                parent.display()
            )
        })?;
    }
    let engram_session_id = qwen3_guest_session_id(&prompt_history_tokens);
    let mut command = Command::new(&script_path);
    command
        .env(
            "SIM_UAPI_W4_CHIPBACKEND_PROFILE",
            runtime.chipbackend_profile,
        )
        .env("SIM_UAPI_W5_PROFILE", w5_profile.name)
        .env("SIM_QWEN3_DENSE_MODEL_ID", &runtime.profile.model_id)
        .env("SIM_QWEN3_DENSE_MODEL_KEY", &runtime.model_key)
        .env("SIM_QWEN3_DENSE_WEIGHTS_PATH", &runtime.weights_path)
        .env(
            "SIM_QWEN3_DENSE_VOCAB_SIZE",
            runtime.profile.vocab_size.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_HIDDEN_SIZE",
            runtime.profile.hidden_size.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_INTERMEDIATE_SIZE",
            runtime.profile.intermediate_size.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_NUM_HIDDEN_LAYERS",
            runtime.profile.num_hidden_layers.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_NUM_ATTENTION_HEADS",
            runtime.profile.num_attention_heads.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_NUM_KEY_VALUE_HEADS",
            runtime.profile.num_key_value_heads.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_HEAD_DIM",
            runtime.profile.head_dim.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_PREFILL_TOKENS",
            runtime.profile.prefill_tokens.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_DECODE_TOKENS",
            runtime.profile.decode_tokens.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_TP_NODES",
            runtime.profile.tp_nodes.to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_HIDDEN_RANGE_BYTES",
            hidden_range_bytes(&runtime.profile).to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_DECODE_HIDDEN_BYTES",
            decode_hidden_bytes(&runtime.profile).to_string(),
        )
        .env(
            "SIM_QWEN3_DENSE_KV_STATE_BYTES",
            kv_state_bytes_for_layer_count(&runtime.profile, runtime.profile.num_hidden_layers)
                .to_string(),
        )
        .env("SIM_QWEN3_GUEST_DECODE_STEPS", args.step_count.to_string())
        .env("SIM_QWEN3_SAMPLER_TOP_K", args.sampler.top_k.to_string())
        .env(
            "SIM_QWEN3_SAMPLER_TOP_P_MILLI",
            args.sampler.top_p_milli.to_string(),
        )
        .env(
            "SIM_QWEN3_SAMPLER_TEMPERATURE_MILLI",
            args.sampler.temperature_milli.to_string(),
        )
        .env("SIM_QWEN3_SAMPLER_SEED", args.sampler.seed.to_string())
        .env(
            "SIM_QWEN3_GUEST_PROMPT",
            args.prompt.clone().unwrap_or_default(),
        )
        .env("SIM_LLM_INFER_PROMPT_TOKEN_IDS", guest_prompt_token_ids)
        .env(
            "SIM_W5_TEST_MEMORY_PREFIX_CACHE_REPLAY_SUFFIX_TOKENS",
            prefix_cache_replay_suffix_token_ids,
        )
        .env("TRACE_FILE", &trace_file)
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());
    command.env("SIM_QWEN3_DENSE_WEIGHTS_PATH", &runtime.weights_path);
    for (key, value) in qwen3_guest_engram_env_vars(&effective_engram, engram_session_id) {
        command.env(key, value);
    }
    if let (Some(config), Some(decisions)) = (&args.memory_decisions, &memory_decisions) {
        for (key, value) in
            w5_memory_decision_env_vars(config, decisions, memory_decision_publication.as_ref())
        {
            command.env(key, value);
        }
    }
    if let Some(config) = &args.memory_runtime_paths {
        command
            .env(
                "SIM_W5_MEMORY_STORE",
                config.store_path.display().to_string(),
            )
            .env(
                "SIM_W5_MEMORY_OBJECT_STORE",
                config.object_store_path.display().to_string(),
            )
            .env(
                "SIM_W5_MEMORY_ENGRAM_STATE",
                config.engram_state_path.display().to_string(),
            )
            .env(
                "SIM_W5_MEMORY_REGISTRY_DIR",
                config.registry_dir.display().to_string(),
            );
        command.env(
            SIM_UAPI_QWEN3_OBJECT_REGISTRY_DIR,
            config.registry_dir.display().to_string(),
        );
        command.env(
            SIM_UAPI_QWEN3_OBJECT_SERVICE_SNAPSHOT,
            config.object_store_path.display().to_string(),
        );
    }
    if let Some(spec) = &engram_simt {
        let spec = &spec.spec;
        command
            .env("SIM_ENGRAM_SIMT_SELECTED_SYMBOL", &spec.symbol)
            .env("SIM_ENGRAM_SIMT_SELECTED_CASE", &spec.case_name)
            .env("SIM_ENGRAM_SIMT_BINARY_PATH", &spec.binary_path)
            .env(
                "SIM_ENGRAM_SIMT_KERNEL_LIBRARY_PATH",
                &spec.kernel_library_path,
            );
    }
    let status = command
        .status()
        .with_context(|| format!("failed to run {}", script_path.display()))?;
    let mut combined = fs::read_to_string(&trace_file).unwrap_or_default();
    if let Some(log_dir) = qwen3_guest_log_dir_from_script_output(&combined, &script_path) {
        combined.push_str(&qwen3_guest_read_log_dir(&log_dir)?);
    }
    let runtime_forward_count =
        qwen3_guest_log_match_count(&combined, "stage uapi_qwen3_range_runtime_forward ");
    let runtime_publish_count = qwen3_guest_log_match_count(
        &combined,
        "stage qwen3_range_forward_runtime_output_publish ",
    );
    let runtime_input_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_range_forward_runtime_input_loaded ");
    let terminal_token_count = qwen3_guest_terminal_tokens(&combined).len();
    let guest_engram_select_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_token_select ");
    let guest_engram_history_wait_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_history_wait ");
    let guest_engram_state_wait_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_state_wait ");
    let guest_engram_state_resolved_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_decode_round_engram_state_resolved ");
    let guest_engram_candidate_publish_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_candidates_publish ");
    let guest_engram_candidate_wait_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_candidates_wait ");
    let guest_engram_selected_wait_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_selected_token_wait ");
    let guest_engram_selected_writeback_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_selected_writeback ");
    let guest_engram_terminal_rewrite_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_engram_terminal_record_rewrite ");
    let shortpath_no_dispatch_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_decode_round_scheduler_no_dispatch ");
    let shortpath_terminal_committed_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_decode_round_terminal_committed ");
    let shortpath_publish_hidden_zero_count = qwen3_guest_log_line_match_count(
        &combined,
        "stage qwen3_w5_memory_shortpath_commit ",
        " publish_hidden=0 ",
    );
    let shortpath_terminal_ready_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_w5_memory_terminal_logits_loaded ");
    let shortpath_terminal_selected_count =
        qwen3_guest_log_match_count(&combined, "stage qwen3_w5_memory_terminal_logits_selected ");
    let shortpath_execute_jump_to_terminal = args
        .memory_decisions
        .as_ref()
        .is_some_and(|config| config.shortpath_execute)
        && memory_decisions
            .as_ref()
            .and_then(|decisions| decisions.shortpath.as_ref())
            .is_some_and(|decision| decision.action == sim_memory::ShortpathAction::JumpToTerminal);
    let expected_shortpath_terminal_hit_count = if shortpath_execute_jump_to_terminal {
        w5_expected_jump_to_terminal_shortpath_hits(memory_decisions.as_ref())
    } else {
        0
    };
    let expected_shortpath_worker_counts = if shortpath_execute_jump_to_terminal {
        w5_expected_jump_to_terminal_worker_counts(memory_decisions.as_ref(), 8)
    } else {
        None
    };
    let engram_shortpath_local_policy =
        effective_engram.enabled && shortpath_execute_jump_to_terminal;
    let worker_counts =
        qwen3_guest_expected_worker_counts(args.step_count, runtime.profile.tp_nodes as usize);
    let expected_runtime_forward_count = worker_counts.range_forwards;
    let expected_runtime_input_count = worker_counts.runtime_inputs;
    let expected_runtime_publish_count = worker_counts.runtime_outputs;
    let expected_terminal_token_count = args.step_count;
    let expected_guest_engram_select_count = if effective_engram.enabled {
        args.step_count
    } else {
        0
    };
    let expected_guest_engram_candidate_publish_count =
        if effective_engram.enabled && !engram_shortpath_local_policy {
            args.step_count
        } else {
            0
        };
    let expected_guest_engram_candidate_wait_count = expected_guest_engram_candidate_publish_count;
    let expected_guest_engram_selected_wait_count = if engram_shortpath_local_policy {
        0
    } else {
        expected_guest_engram_select_count
    };
    let expected_guest_engram_selected_writeback_count = expected_guest_engram_select_count;
    let expected_guest_engram_history_wait_count = if engram_shortpath_local_policy {
        0
    } else {
        qwen3_guest_expected_engram_history_state_waits(effective_engram.enabled, args.step_count)
    };
    let expected_guest_engram_state_wait_count = expected_guest_engram_history_wait_count;
    let expected_guest_engram_state_resolved_count = expected_guest_engram_history_wait_count;
    let timing_summary = qwen3_guest_timing_summary(&combined);
    let terminal_tokens = qwen3_guest_terminal_tokens(&combined);
    let guest_engram_selected_tokens = qwen3_guest_engram_selected_tokens(&combined);
    let guest_engram_select_history_lengths = qwen3_guest_engram_select_history_lengths(&combined);
    let guest_engram_history_lengths = qwen3_guest_engram_history_lengths(&combined);
    let guest_engram_candidate_counts = qwen3_guest_engram_candidate_counts(&combined);
    let terminal_text = qwen3_guest_terminal_text_lossy(&terminal_tokens, &runtime.weights_path);
    let pass = qwen3_guest_w5_pass_marker_present(&combined);
    println!(
        "  guest_worker_summary: pass={} steps={} range_forwards={} runtime_inputs={} runtime_outputs={} terminal_tokens={}",
        pass, args.step_count, runtime_forward_count, runtime_input_count, runtime_publish_count, terminal_token_count
    );
    if shortpath_execute_jump_to_terminal {
        println!(
            "{}",
            qwen3_guest_shortpath_summary_line(
                shortpath_terminal_ready_count,
                shortpath_terminal_selected_count,
                expected_shortpath_terminal_hit_count,
                runtime_forward_count,
                runtime_input_count,
                runtime_publish_count,
                expected_runtime_forward_count,
                expected_runtime_input_count,
                expected_runtime_publish_count,
            )
        );
    }
    if !terminal_tokens.is_empty() {
        println!("  terminal_tokens: {:?}", terminal_tokens);
        match &terminal_text {
            Some(text) => println!("  generated_text_lossy: {}", text.escape_debug()),
            None => println!("  generated_text_lossy: <tokenizer unavailable>"),
        }
    }
    if !status.success() || !pass {
        anyhow::bail!(
            "qwen3 guest decode worker failed: status={} pass={}",
            status,
            pass
        );
    }
    let engram_report = if effective_engram.enabled {
        let session_id = qwen3_guest_session_id(&prompt_history_tokens);
        if effective_engram.pool == Qwen3EngramPool::Obmm {
            Some(qwen3_guest_engram_report_from_guest_log(
                &effective_engram,
                session_id,
                &prompt_history_tokens,
                &combined,
            )?)
        } else {
            Some(qwen3_guest_engram_report(
                &effective_engram,
                session_id,
                &prompt_history_tokens,
                &combined,
            )?)
        }
    } else {
        None
    };
    let guest_engram_object_transport =
        if effective_engram.enabled && effective_engram.pool == Qwen3EngramPool::Obmm {
            Some(qwen3_guest_engram_object_transport_report(&combined))
        } else {
            None
        };
    if let Some(report) = &engram_report {
        print_qwen3_guest_engram_report(report);
        if let Some(transport) = &guest_engram_object_transport {
            println!(
                "  guest_engram_object_transport: object_puts={} object_waits={} candidate_publishes={} candidate_waits={} decision_publishes={} selected_waits={} selected_writebacks={} history_waits={} state_waits={} state_resolved={} payload_write_bytes={} payload_read_bytes={} queue_submits={} queue_delivers={} checksum={:#x}",
                transport.object_puts,
                transport.object_waits,
                transport.candidate_publishes,
                transport.candidate_waits,
                transport.decision_publishes,
                transport.selected_waits,
                transport.selected_writebacks,
                transport.history_waits,
                transport.state_waits,
                transport.state_resolved,
                transport.payload_write_bytes,
                transport.payload_read_bytes,
                transport.queue_submits,
                transport.queue_delivers,
                transport.checksum
            );
        }
        if report.selected_tokens != terminal_tokens {
            anyhow::bail!(
                "engram policy selected tokens are not wired into guest writeback yet: selected={:?} terminal={:?}",
                report.selected_tokens,
                terminal_tokens
            );
        }
        if !guest_engram_selected_tokens.is_empty() {
            let expected_terminal_rewrites = qwen3_guest_engram_expected_terminal_rewrites(report);
            let expected_history_lengths =
                if guest_engram_select_history_lengths.len() == args.step_count {
                    guest_engram_select_history_lengths
                        .iter()
                        .map(|length| length + 1)
                        .collect::<Vec<_>>()
                } else {
                    (0..args.step_count)
                        .map(|step| prompt_history_tokens.len() as u64 + step as u64 + 1)
                        .collect::<Vec<_>>()
                };
            let blocked_writeback_tokens = terminal_tokens
                .iter()
                .copied()
                .filter(|token| effective_engram.blocked_token_ids.contains(token))
                .collect::<Vec<_>>();
            println!(
                "  guest_engram_writeback: selected_tokens={:?} terminal_tokens={:?} blocked_token_ids={:?} blocked_writeback_tokens={:?} history_lengths={:?} candidate_counts={:?} candidate_publishes={} candidate_waits={} selected_waits={} selected_writebacks={} terminal_rewrites={} select_logs={} history_waits={} state_waits={} state_resolved={} matches_terminal={}",
                guest_engram_selected_tokens,
                terminal_tokens,
                effective_engram.blocked_token_ids,
                blocked_writeback_tokens,
                guest_engram_history_lengths,
                guest_engram_candidate_counts,
                guest_engram_candidate_publish_count,
                guest_engram_candidate_wait_count,
                guest_engram_selected_wait_count,
                guest_engram_selected_writeback_count,
                guest_engram_terminal_rewrite_count,
                guest_engram_select_count,
                guest_engram_history_wait_count,
                guest_engram_state_wait_count,
                guest_engram_state_resolved_count,
                guest_engram_selected_tokens == terminal_tokens
            );
            if guest_engram_selected_tokens != terminal_tokens {
                anyhow::bail!(
                    "guest engram selected tokens do not match terminal writeback: selected={:?} terminal={:?}",
                    guest_engram_selected_tokens,
                    terminal_tokens
                );
            }
            if !engram_shortpath_local_policy
                && guest_engram_history_lengths != expected_history_lengths
            {
                anyhow::bail!(
                    "guest engram history object lengths are wrong: got={:?} expected={:?}",
                    guest_engram_history_lengths,
                    expected_history_lengths
                );
            }
            let expected_candidate_counts = report
                .steps
                .iter()
                .map(|step| step.candidates.len() as u64)
                .collect::<Vec<_>>();
            if !engram_shortpath_local_policy
                && guest_engram_candidate_counts != expected_candidate_counts
            {
                anyhow::bail!(
                    "guest engram candidate object counts are wrong: got={:?} expected={:?}",
                    guest_engram_candidate_counts,
                    expected_candidate_counts
                );
            }
            if !blocked_writeback_tokens.is_empty() {
                anyhow::bail!(
                    "guest engram blocked tokens reached writeback: blocked={:?} terminal={:?}",
                    blocked_writeback_tokens,
                    terminal_tokens
                );
            }
            if guest_engram_terminal_rewrite_count != expected_terminal_rewrites {
                anyhow::bail!(
                    "guest engram terminal rewrite count is wrong: rewrites={} expected={}",
                    guest_engram_terminal_rewrite_count,
                    expected_terminal_rewrites
                );
            }
        }
    }
    if timing_summary.worker_count > 0 {
        println!(
            "  guest_worker_timing: workers={} max_total_ms={} max_setup_ms={} max_seed_payload_ms={} max_descriptor_ms={} max_compute_window_ms={} max_submit_ms={} max_base_submit_ms={} max_doorbell_submit_ms={} max_batch_submit_ms={} max_dispatch_ms={} max_doorbell_log_ms={} max_batch_sleep_ms={} max_post_batch_ms={} max_completion_decode_ms={} max_compute_unaccounted_ms={} max_publish_ms={} max_input_wait_ms={} max_unaccounted_ms={} max_barrier_ms={}",
            timing_summary.worker_count,
            timing_summary.max_total_ms,
            timing_summary.max_setup_ms,
            timing_summary.max_seed_payload_ms,
            timing_summary.max_descriptor_ms,
            timing_summary.max_compute_window_ms,
            timing_summary.max_submit_ms,
            timing_summary.max_base_submit_ms,
            timing_summary.max_doorbell_submit_ms,
            timing_summary.max_batch_submit_ms,
            timing_summary.max_dispatch_ms,
            timing_summary.max_doorbell_log_ms,
            timing_summary.max_batch_sleep_ms,
            timing_summary.max_post_batch_ms,
            timing_summary.max_completion_decode_ms,
            timing_summary.max_compute_unaccounted_ms,
            timing_summary.max_publish_ms,
            timing_summary.max_input_wait_ms,
            timing_summary.max_unaccounted_ms,
            timing_summary.max_barrier_ms
        );
    }
    let worker_pipeline_counts_ok = if shortpath_execute_jump_to_terminal {
        if let Some(expected) = expected_shortpath_worker_counts {
            runtime_forward_count == expected.range_forwards
                && runtime_publish_count == expected.runtime_outputs
                && runtime_input_count == expected.runtime_inputs
                && shortpath_no_dispatch_count == expected.no_dispatches
                && shortpath_terminal_committed_count == expected.no_dispatches
                && shortpath_publish_hidden_zero_count == expected_shortpath_terminal_hit_count
        } else {
            false
        }
    } else {
        runtime_forward_count == expected_runtime_forward_count
            && runtime_publish_count == expected_runtime_publish_count
            && runtime_input_count == expected_runtime_input_count
    };
    let shortpath_terminal_counts_ok = expected_shortpath_terminal_hit_count == 0
        || (shortpath_terminal_ready_count == expected_shortpath_terminal_hit_count
            && shortpath_terminal_selected_count == expected_shortpath_terminal_hit_count);
    if !worker_pipeline_counts_ok
        || !shortpath_terminal_counts_ok
        || terminal_token_count != expected_terminal_token_count
        || guest_engram_select_count != expected_guest_engram_select_count
        || guest_engram_candidate_publish_count != expected_guest_engram_candidate_publish_count
        || guest_engram_candidate_wait_count != expected_guest_engram_candidate_wait_count
        || guest_engram_selected_wait_count != expected_guest_engram_selected_wait_count
        || guest_engram_selected_writeback_count != expected_guest_engram_selected_writeback_count
        || guest_engram_history_wait_count != expected_guest_engram_history_wait_count
        || guest_engram_state_wait_count != expected_guest_engram_state_wait_count
        || guest_engram_state_resolved_count != expected_guest_engram_state_resolved_count
    {
        anyhow::bail!(
            "qwen3 guest decode worker incomplete: range_forwards={}/{} runtime_inputs={}/{} runtime_outputs={}/{} shortpath_no_dispatch={}/{} shortpath_terminal_committed={}/{} shortpath_publish_hidden_zero={}/{} shortpath_boundary_hits={}/{} shortpath_terminal_selects={}/{} terminal_tokens={}/{} engram_selects={}/{} engram_candidate_publishes={}/{} engram_candidate_waits={}/{} engram_selected_waits={}/{} engram_selected_writebacks={}/{} engram_history_waits={}/{} engram_state_waits={}/{} engram_state_resolved={}/{}",
            runtime_forward_count,
            expected_shortpath_worker_counts
                .map(|counts| counts.range_forwards)
                .unwrap_or(expected_runtime_forward_count),
            runtime_input_count,
            expected_shortpath_worker_counts
                .map(|counts| counts.runtime_inputs)
                .unwrap_or(expected_runtime_input_count),
            runtime_publish_count,
            expected_shortpath_worker_counts
                .map(|counts| counts.runtime_outputs)
                .unwrap_or(expected_runtime_publish_count),
            shortpath_no_dispatch_count,
            expected_shortpath_worker_counts
                .map(|counts| counts.no_dispatches)
                .unwrap_or(0),
            shortpath_terminal_committed_count,
            expected_shortpath_worker_counts
                .map(|counts| counts.no_dispatches)
                .unwrap_or(0),
            shortpath_publish_hidden_zero_count,
            expected_shortpath_terminal_hit_count,
            shortpath_terminal_ready_count,
            expected_shortpath_terminal_hit_count,
            shortpath_terminal_selected_count,
            expected_shortpath_terminal_hit_count,
            terminal_token_count,
            expected_terminal_token_count,
            guest_engram_select_count,
            expected_guest_engram_select_count,
            guest_engram_candidate_publish_count,
            expected_guest_engram_candidate_publish_count,
            guest_engram_candidate_wait_count,
            expected_guest_engram_candidate_wait_count,
            guest_engram_selected_wait_count,
            expected_guest_engram_selected_wait_count,
            guest_engram_selected_writeback_count,
            expected_guest_engram_selected_writeback_count,
            guest_engram_history_wait_count,
            expected_guest_engram_history_wait_count,
            guest_engram_state_wait_count,
            expected_guest_engram_state_wait_count,
            guest_engram_state_resolved_count,
            expected_guest_engram_state_resolved_count
        );
    }
    if let Some(store_path) = w5_boundary_observation_store_path(args) {
        qwen3_flush_w5_memory_runtime_commits()
            .map_err(|err| anyhow::anyhow!("flush W5 runtime Memory Service commits: {err}"))?;
        let summary_path =
            qwen3_guest_summary_file_from_script_output(&combined).ok_or_else(|| {
                anyhow::anyhow!(
                    "W5 run used Memory Service store but did not report a summary_file path"
                )
            })?;
        let boundary_lookup_now_us = cli_now_us();
        let observation_ids_result = record_w5_runtime_boundary_observations_from_summary(
            store_path,
            &summary_path,
            &runtime,
            args.step_count,
            prompt_history_tokens.len() as u64,
            boundary_lookup_now_us,
        );
        let mut boundary_observations_skipped = false;
        let observation_ids = match observation_ids_result {
            Ok(observation_ids) => observation_ids,
            Err(err)
                if shortpath_terminal_selected_count > 0
                    && format!("{err:#}").contains("has no boundary observations to persist") =>
            {
                boundary_observations_skipped = true;
                Vec::new()
            }
            Err(err) => return Err(err),
        };
        println!(
            "{}",
            w5_memory_boundary_observations_recorded_line(
                store_path,
                &summary_path,
                &observation_ids,
                args.step_count,
                boundary_observations_skipped.then_some("shortpath_no_range_exit"),
            )
        );
        if args.memory_post_run_promote && !observation_ids.is_empty() {
            let object_registry_dir = args
                .memory_runtime_paths
                .as_ref()
                .map(|config| config.registry_dir.as_path());
            let object_store_path = args
                .memory_runtime_paths
                .as_ref()
                .map(|config| config.object_store_path.as_path());
            let promoted = promote_w5_runtime_terminal_shortpath_artifacts_from_summary(
                store_path,
                &summary_path,
                &runtime,
                prompt_history_tokens.len() as u64,
                boundary_lookup_now_us,
                boundary_lookup_now_us,
                object_registry_dir,
                object_store_path,
            )?;
            println!(
                "  memory_runtime_shortpath_artifacts_promoted: store={} summary={} promoted={}",
                store_path.display(),
                summary_path.display(),
                promoted
            );
        } else if !args.memory_post_run_promote && !observation_ids.is_empty() {
            println!(
                "  memory_runtime_shortpath_artifacts_promoted: store={} summary={} promoted=0 status=skipped reason=post_run_promote_disabled",
                store_path.display(),
                summary_path.display()
            );
        }
        let prefix_cache_artifact_id = register_w5_runtime_prefix_cache_artifact(
            store_path,
            &runtime,
            &prompt_history_tokens,
            cli_now_us(),
        )
        .context("register W5 runtime prefix cache artifact")?;
        if let Some(artifact_id) = prefix_cache_artifact_id {
            println!(
                "  memory_runtime_prefix_cache_artifact: store={} artifact={} status=registered",
                store_path.display(),
                artifact_id
            );
        } else {
            println!(
                "  memory_runtime_prefix_cache_artifact: store={} status=skipped reason=no_verified_step0_kv_artifacts",
                store_path.display()
            );
        }
        let object_service = if let Some(bootstrap) = &args.memory_runtime_paths {
            load_lingqu_object_service_snapshot_file(&bootstrap.object_store_path)
                .ok()
                .flatten()
                .and_then(|snapshot| LingquObjectServiceStub::import_snapshot(snapshot).ok())
        } else {
            None
        };
        if args.memory_runtime_boundary_lookup && !observation_ids.is_empty() {
            let report = run_w5_runtime_boundary_lookups(
                store_path,
                &observation_ids,
                boundary_lookup_now_us,
                object_service.as_ref(),
                &args.shortpath_match_mode,
                args.min_match_score_milli,
                args.min_terminal_margin_milli,
                args.approximate_requires_verify,
                args.min_source_confidence_milli,
            )?;
            println!(
                "  memory_runtime_boundary_lookup: store={} observations={} decisions={} continue={} jump_to_layer={} jump_to_terminal={} require_verify={} first_decision_id={} last_decision_id={}",
                store_path.display(),
                report.observation_count,
                report.decision_count,
                report.continue_count,
                report.jump_to_layer_count,
                report.jump_to_terminal_count,
                report.require_verify_count,
                report.first_decision_id.as_deref().unwrap_or(""),
                report.last_decision_id.as_deref().unwrap_or("")
            );
        }
    }
    Ok(())
}

